namespace NodeVocab
{
   struct Entry
   {
      const char* type;
      const char* category;
      const char* words; // space-separated, lowercase
      const char* help;  // the in-app help text (Menu > Help), English
   };
   inline constexpr Entry kEntries[] = {
      { "3D View", "3D", "width height samples shadows exposure bloom ao supersample tonemap threshold radius shadow quality bias softness strength dof aperture focus distance blades rotation ratio ambient env intensity float render pass mist start depth falloff cavity ridge valley curvature motion blur shutter max view shading solid lighting color single matcap specular studio world projection dome angle tilt fisheye lens lat min lon engine pt bounces scene", "The final stage of a 3D patch. Right-click any 3D node and choose Add to 3D View to bring its output in, then arrange it in the 3D View panel (Shift+3): G move, R rotate, S scale, X Y Z to lock an axis, hold {mod} to snap. Arranging never changes the node, and whatever the node animates keeps playing through the placement: build and change things on the canvas, compose them here. Transparent until you set a world in its World tab. Keys are Blender's, including the 3D cursor (Shift+right-click), pivot (period), orientation (comma), local view (/) and keyframes (I). F12 renders a picture and {mod}+F12 the animation, through an Output node." },
      { "Analog", "Synths", "freq glide bend pitch fine fine1 semi1 oct1 fine2 semi2 oct2 pw pw1 vol osc1vol osc2vol voices spread fm detune osc sub noise filter cutoff reso resonance drive key track attack decay sustain release wave1 saw square triangle sine wave2 analog flt ladder lp hp bp notch ms diode oct semi notes", "A classic polyphonic virtual-analog synth voice with two analog-style oscillators (osc1 unison stack, osc2 tuning/detune/sync, sub osc one octave down, white noise, pre-filter drive stage, nonlinear ZDF filter (Moog ladder, MS-20, diode ladder or SVF), and amplitude ADSR across up to 8 voices). Detune reads as the stack's true total width in cents, distributed unevenly across the stack the way separately mistuned circuits sit. Spread is stereo width: it splits the stack across two independent drive/filter chains and places each voice card in the image, so the sides carry different oscillators rather than one panned copy." },
      { "Armature", "3D", "axis bones envelope curl direction twist wave length phase pose0 pose0x pose0y pose0z pose1 pose1x pose1y pose1z pose2 pose2x pose2y pose2z pose3 pose3x pose3y pose3z pose4 pose4x pose4y pose4z pose5 pose5x pose5y pose5z pose6 pose6x pose6y pose6z pose7 pose7x pose7y pose7z pose8 pose8x pose8y pose8z pose9 pose9x pose9y pose9z pose10 pose10x pose10y pose10z pose11 pose11x pose11y pose11z pose12 pose12x pose12y pose12z pose13 pose13x pose13y pose13z pose14 pose14x pose14y pose14z pose15 pose15x pose15y pose15z ik joint chain weight pole weights open 3d view path", "Bends any geometry with a chain of bones along an axis or the path curve. Curl, twist and wave bend it; Open in 3D View enters Pose mode, where IK works on it too, and W paints the weights ([ ] size, Ctrl removes)." },
      { "Arpeggiator", "Notes", "up down random as played repeat x2 x4 join spread stairs diverge converge octaves rate beats seconds gate percent step gates use global timing classic 32t notes", "Holds whatever notes are currently down and replays them one at a time on its own clock, either synced to tempo (a note division) or free-running in seconds. Up/Down/Up-Down/Down-Up/As Played order the held notes by pitch or by the order they were pressed; Converge alternates outside-in (lowest, highest, next-lowest...), Diverge alternates inside-out from the middle; Random picks one per step. Repeat x2/x4 fires each note 2 or 4 times in a row before advancing. Stairs Up/Down walks the pattern in overlapping two-note steps (C E, E G, G C...). Join and Spread only differ once octaves is above 1: Spread stacks the pattern octave-by-octave (C3 D3 E3, C4 D4 E4), Join interleaves each note's octaves together (C3 C4, D3 D4, E3 E4), and Join/Spread alternates between the two every full pass - at octaves = 1 all three play identically to Up. The 8-step gate grid below the readout is the primary control: click or drag across cells to mute individual steps without changing the note order (advancing past a muted step still moves the pattern forward, punching a rhythmic hole rather than skipping a note), and the lit cell tracks the currently-sounding step. Octaves stacks the pattern up to 4 octaves higher. Gate sets how much of each step the note actually sounds for before its off. Preset loads a complete starting point (mode, octaves, rate, gate and gate pattern) in one click." },
      { "Array", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only move count offset rotate rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Duplicates the input mesh in a line or radial ring. Count sets how many copies; radial mode spaces them by Radius, linear mode by Offset X/Y/Z; each copy can additionally rotate/scale a step further than the last." },
      { "Arrow", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "An arrow shape - direction follows the Rotation control." },
      { "Arrow 3D", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides shaft radius bevel segments head length super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A 3D arrow mesh - shaft plus arrowhead. Named with a '3D' suffix because the 2D Shape node already has its own 'Arrow'." },
      { "Audio Analyze", "Modulators", "attack release onset hold start listening audio low mid high b1 b2 b3 b4 b5 b6 b7 b8", "Extracts level, band and onset values from audio for modulation - patch any audio source into it (Audio In, Audio File, a Filter, a Mixer, an Oscillator) and every output can drive any slider in the graph. With nothing patched in it falls back to its own Start listening button, a live tap on the system's default input device. It passes its input straight through, so it can sit inline in a chain as well as hang off one as a tap. Outputs: level, low/mid/high, onset, and b1-b8, eight raw frequency bands running low to high." },
      { "Audio Color Ramp", "Compositing", "intensity glow band expansion continuous spectrum interpolation interp linear constant smooth bands count min brightness cross0 cross1 cross2 cross3 cross4 cross5 cross6 color0 gain0 color1 gain1 color2 gain2 color3 gain3 color4 gain4 color5 gain5 color6 gain6 color7 gain7 img audio", "Splits incoming audio into up to 8 frequency bands - drag the dividers right on the spectrum display to resize them - and assigns each one a colour, VIBGYOR by default from low to high. With no image patched in it outputs the resulting gradient standalone; patch one into its optional image input and it grades that image by luminance through the same audio-reactive palette instead." },
      { "Audio Displacement", "3D", "normal waveform spectral fft bands acoustic ripples cymatics chladni directional axis strength frequency damping attack decay midlevel subdivide flat shade flip normals inherit material selection only color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo audio", "Deforms a geometry input using live audio patched into its second pin - five modes, each a different physical reading of the same signal: Normal Waveform pushes each vertex along its own normal by the oscilloscope trace, Spectral Bands maps the FFT across the X/U axis, Acoustic Ripples sends concentric waves out from the centre, Cymatics (Chladni) solves the standing-wave modal pattern for mode numbers m/n (the classic salt-on-a-plate figures), and Directional Axis pushes along a fixed local X/Y/Z. Attack/decay shape how fast the surface answers; Subdivide adds the resolution a displacement needs to be visible at all." },
      { "Audio File", "Modulators", "path loop follow transport monitor attack release pitch choose audio", "Loads an audio file for playback and Audio Analyze to read. Keeps analysing even while muted - the 'audible' checkbox only controls monitoring." },
      { "Audio Filter", "AudioEffects", "freq db env rate div drive lp audio", "One filter, one of 17 types (LP/HP at 12/24/36 dB, BP, notch, shelves, peak, all-pass, comb, and ladder, MS-20 and diode models that sing at the top of Q). Drag the handle on the response curve to set frequency and gain, Shift-drag to set Q - the picture is the control." },
      { "Audio In", "Utility", "db channel device name", "Captures the default input device (mic or line-in) as a live audio source for the effects graph - patch it into a Filter, Delay, Mixer or straight to Audio Out. Trim is a plain gain stage; the mic tap starts the first time this node cooks and macOS will prompt for microphone permission then, so it stays idle until it's actually in a patch. The capture runs on its own engine bound to the system default input, independently of whichever output device is selected, and the header line says why it isn't live when it isn't." },
      { "Audio Meter", "Utility", "audio", "A stereo level meter: separate L and R bars on a shared -60 to +3 dBFS scale, each showing RMS (solid) inside peak (faint), a peak-hold line, and the channel's highest peak as a number on top, which turns red once that channel has reached 0 dBFS. Audio passes through unchanged. It measures whatever its input is patched to even with its output left unconnected, so it can hang off any cable as a tap. Click the meter to clear the peak numbers, holds and clip." },
      { "Audio Out", "Utility", "format index record directory live wav flac mp3 choose audio", "The terminal node for audio, the counterpart of Output for images: whatever is patched in is summed into the selected output device. It has no processing of its own and no output pin. Two cables into one Audio Out is refused on purpose - route them through a Mixer instead, which is the only node in the app that sums audio. With several Audio Outs, plugin delay is compensated between them so they land together; press live to opt this one out when you are playing through it and want the lowest delay." },
      { "Audio Ribbon", "3D", "width height segments smoothing rot uniform color metallic roughness opacity shading lit normals uv flat emission ior", "Turns audio into a 3D mesh in the most literal way available: the waveform extruded as a flat ribbon through space, Segments points wide, with width/height scale and its own transform. Smoothing damps the trace between frames so it reads as a surface rather than a flicker. Takes audio on its own pin - it is a geometry source, so it goes into Render 3D, not into Audio Out." },
      { "Audio Texture", "Source", "waveform spectrum window index smoothing", "Renders incoming audio as an image, so every image node in the app becomes an audio visualiser: Waveform draws the oscilloscope trace, Spectrum the FFT magnitude across a chosen window size. gain scales the drawn amplitude, smoothing damps it between frames. Distinct from Audio Analyze, which produces numbers for modulation - this produces pixels." },
      { "Audio to CV", "Modulators", "att attack ms rel release peak rms min val max audio", "Converts audio into a modulator through an amplitude follower - Peak or RMS detection with its own attack and release. The lightweight, single-output counterpart of Audio Analyze: reach for this when all you want is 'this parameter follows how loud that is', and for Audio Analyze when you want bands, onsets and a passthrough." },
      { "Bake", "3D", "bake ao curvature normal thickness sculpt samples distance geo", "Geometry in, image out: the mesh drawn in its own UV space. AO, curvature, position, normal or thickness, so the image can go through any 2D effect and back into a Material map. Sculpt bakes an upstream Sculpt node into a normal map for the unsculpted mesh: put Bake after the Sculpt, then feed the image to the Material's normal map on the mesh before it. Needs UVs (Model 3D, primitives, or UV Project). Bakes again when the mesh changes." },
      { "Bevel", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border move width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Rounds or chamfers every sharp edge (angle above 'sharp angle'). 'width' is the bevel size, 'segments' 1 gives a flat chamfer and more give a smooth round. Result stays closed; width is limited by the shortest sharp edge." },
      { "Bitcrush", "AudioEffects", "downsample rate bits analog dither audio", "Sample-rate reduction (rate, zero-order hold) and bit-depth quantization (bits) - the two classic lo-fi digital degradations, independent of each other." },
      { "Blend", "Compositing", "normal darken multiply color burn linear darker lighten screen dodge add lighter overlay soft light hard vivid pin difference exclusion subtract divide hue saturation luminosity average negation reflect glow erase anti opacity blend fix headroom", "Two inputs and 32 blend modes - the full Normal / Multiply / Screen / Overlay / Hue / Saturation / Colour / Luminosity set, plus Erase." },
      { "Blend Audio", "Utility", "blend", "A two-input crossfader: blend 0 is A only, 1 is B only, 0.5 an equal-power centre. Not a second place to sum two signals (that's Mixer) - it picks a point between them, and its blend knob has a modulation pin, so an LFO or Macro can sweep the crossfade." },
      { "Blob", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "An organic, wobbly rounded shape - randomised per Seed-like controls rather than a precise geometric primitive." },
      { "Bouncing Balls", "Notes", "shape circle square triangle balls num ball lo range low hi high root use global", "Balls bounce around inside a shape and emit a random note in lo..hi range every time one hits the wall, flashing orange briefly on the hit. Shape swaps the boundary between circle, square and triangle; size and speed are the balls' own; balls sets how many are simulated at once." },
      { "CV Recorder", "Modulators", "no cable constant low high playing data record", "Records any modulator patched into its input and plays it back. Press Rec to capture (live input passes through while recording), press Rec again to stop and it starts looping straight away. speed is the playback rate - 2x plays the take twice as fast - and low/high map the take onto an output range. Takes are timed in beats, so they follow the tempo and pause with the transport (up to 64 beats), and they are saved with the patch. With nothing patched in, it records its own in knob, so you can perform a gesture by hand." },
      { "CV to Pitch", "Modulators", "no cable constant range low high major natural minor harmonic melodic dorian phrygian lydian mixolydian locrian pentatonic blues whole tone chromatic root glide ms maths", "Quantizes a modulator to semitone steps over range low..high, shown as a large +/-N st readout. Still outputs 0..1 like any modulator - it just restricts where in 0..1 the value can land, so the span maps onto whole semitones. Scale/root snap to scale degrees instead of every semitone (chromatic = off); glide adds portamento between steps, passing through unquantized values in transit on purpose." },
      { "Camera", "3D", "projection perspective orthographic ortho height fov shift sensor width fit display limits name mist distance orbit azimuth elevation target roll near far beat per", "A 3D viewpoint. Patch it into a Render 3D node's camera input to render from it instead of the default view." },
      { "Capsule", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A cylinder with hemispherical caps - 'tube' sets the cap/body radius." },
      { "Chevron", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner thick radius sides inner ratio rotation fill color opacity stroke feather bg", "An angled bracket / chevron shape." },
      { "Chorder", "Notes", "major natural minor harmonic melodic dorian phrygian lydian mixolydian locrian pentatonic blues whole tone chromatic root notes chord rate beats strum ms hu time humanize timing vel velocity oct up upper harmonics use global step chords random vi iv iii bars each ii isus4 vsus2 isus2 vsus4 canon descending vii custom length prog steps deg0 type0 deg1 type1 deg2 type2 deg3 type3 deg4 type4 deg5 type5 deg6 type6 deg7 type7", "A self-playing generative chord engine. Every groove step it picks a random scale degree and stacks chord-sized thirds on top of it, in key. Strum spaces each chord tone's onset apart instead of firing them all at once; humanise timing and velocity add per-note randomness on top; notes sets how many notes stack into each chord, length how many chords a progression plays before it loops, and oct up is the chance a chord gets an extra note an octave above one of its tones. The chords dropdown picks how chords are chosen. random walks functional harmony on its own; a preset or custom plays the progression strip below, one chord per cell as a Roman numeral with its type (triad, 7, sus2 or sus4), where - holds the chord before; click a cell for the next chord and right-click for the previous. length sets how many cells play before the loop (random mode ignores it). With Global Scale on, scale and root follow the project key." },
      { "Chorus", "AudioEffects", "delay spread taps depth feedback rate div analog audio", "2 or 3 detuned voices of one modulated delay line, LFO depth/rate, spread offsets the right channel's LFO phase for width." },
      { "Circle", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A filled/stroked circle - one of the Shape vector primitives, with size, feather, stroke and background controls." },
      { "Cloth", "3D", "pinned pin top edge corners border stiffness iterations damping mass gravity wind turbulence collide with ground height bounce friction hold shape retention bending distance collider inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "A cloth simulation over an input mesh - stiffness, bending, iterations, damping, mass and shape retention, plus gravity, wind, optional ground collision and an optional collider mesh it drapes over. 'Reset' re-drops the cloth from its rest pose." },
      { "Color Ramp", "Compositing", "interpolation interp linear constant oklab oklch stop count stop0 color0 stop1 color1 stop2 color2 stop3 color3 stop4 color4 stop5 color5 stop6 color6 stop7 color7 stop8 color8 stop9 color9 stop10 color10 stop11 color11 stop12 color12 stop13 color13 stop14 color14 stop15 color15 stop16 color16 stop17 color17 stop18 color18 stop19 color19 stop20 color20 stop21 color21 stop22 color22 stop23 color23 stop24 color24 stop25 color25 stop26 color26 stop27 color27 stop28 color28 stop29 color29 stop30 color30 stop31 color31", "Recolors any 0-1 grayscale input through user-authored stops, up to 32 of them, with linear, constant, Oklab or OKLCh interpolation (the Oklab modes mix perceptually, so blue-to-yellow stays bright instead of going grey; OKLCh also keeps saturation by travelling around the hue wheel). Unlike Gradient Map, it has no shape of its own - the shape comes from upstream." },
      { "Comment", "Compositing", "text width height color font", "A free-floating note on the canvas - has no image input or output, just text. Double-click to edit." },
      { "Compare", "Modulators", "operation op no cable constant tolerance", "Outputs 1 when the comparison holds, 0 otherwise - >, >=, <, <=, ==, != between two modulators, with a tolerance for the equality checks." },
      { "Cone", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A cone - Sides sets how many-sided." },
      { "Constant", "Modulators", "", "Outputs one fixed number - the simplest possible modulator, useful for feeding a Math input or a modulation slot that expects a cable rather than manual control." },
      { "Convolution Reverb", "AudioEffects", "shape material distance decay spread file room load hall audio", "A reverb whose room you design: shape (room, hall, chamber, tunnel), size, material (soft and dull to hard and bright), distance from the source, decay time and stereo spread. The node builds that room's impulse response in the background and the picture shows it. 'load file' uses a recorded impulse response instead (up to 10 s); the design controls then grey out. It adds no latency." },
      { "Crescent", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A crescent-moon shape - two overlapping circles subtracted from each other." },
      { "Cross", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A plus-sign / cross shape." },
      { "Cube", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A subdivided cube/box." },
      { "Curve", "3D", "kind catmull rom bezier spline linear preset arc spiral wave scatter circle points point count smoothness segments closed spread height twist radius sides taper color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface", "A generative parametric curve/tube (line, circle, spiral, helix and other presets) extruded into a mesh, with point count, smoothness, spread, height, twist and tube radius/taper controls." },
      { "Curve Ops", "3D", "resample simplify smooth offset tolerance count iterations strength distance arc steps tube radius sides curve", "Curve in, curve out. Resample spaces points evenly along the length, Simplify drops points that barely change the shape (within 'tolerance'), Smooth relaxes corners while the ends stay put, Offset draws a parallel curve at a signed distance in the XY plane with round outer corners. The result can still drive a Path and shows as a thin tube." },
      { "Curves", "Compositing", "channel active rgb red green blue exact line headroom curve", "Shadow / midtone / highlight lift plus an S-curve control, per RGB channel or all together. Drag points on the curve to bend it, click empty curve to add a point, right-click a point to remove it." },
      { "Cycle Shaper", "AudioEffects", "waveform thresh threshold smooth analog sine square audio", "Replaces every wavecycle of the input with a clean geometric waveform (Sine, Square, Triangle) of the same period and peak amplitude. Timbre is rebuilt while pitch and rhythm survive. Latency is one wavecycle." },
      { "Cylinder", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A cylinder - Sides sets how many-sided (low values give a prism)." },
      { "Decimate", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps move ratio lock border width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Reduces triangle count while keeping the overall shape (quadric error edge collapse). 'keep' is the fraction of triangles to leave; 'lock border' holds open edges in place. UVs, colours and hard shading survive; very low settings stop when no safe collapse remains." },
      { "Delaunay Mesh", "3D", "plane xy xz yz alive only max points inset", "Point cloud in (a mesh is flagged red and ignored; use Mesh to Points first), triangulated surface out. Use it to turn a scatter into a terrain or low-poly surface. Points are projected onto the chosen plane, joined into Delaunay triangles (no sliver-prone long edges), and lifted back to their real 3D positions, so a scatter with height becomes a terrain. 'max points' thins very large clouds." },
      { "Delay", "AudioEffects", "bounce rate div time ms feedback tone pan duck ducking analog wow flutter saturation diffusion bars audio", "A fractional delay line: time (tempo-synced by default, or free ms with 'sync to tempo' off), tone (bipolar tilt on the repeats), feedback (past 100% on purpose for self-oscillation - the output is soft-clipped, not the feedback itself), pan, duck (sidechains the wet signal off the dry input) and a bounce switch that cross-feeds left/right instead of repeating in place. The tape switch puts a tape machine in the loop: wow (slow pitch drift), flutter (fast wobble), saturation (the repeats round off and lose a little level each pass, like a hot tape) and diffusion (the repeats smear into a wash without changing their timing), with the band-limit filters it always had." },
      { "Delete", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected instead move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Deletes the faces marked by an upstream Select op, or all faces with selection-only off. With 'keep selected instead' it keeps the selection and deletes the rest. After an Instance on Points it drops whole instances instead of faces." },
      { "Delete Selected", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected instead move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Deletes the faces marked by an upstream Select op - or, with 'keep selected instead', deletes everything else and keeps only the selection." },
      { "Depth Projection", "3D", "projection perspective planar ortho radial li dar cylindrical points mesh source depth luminance red alpha green blue inv color turbo viridis thermal ocean solid tint fov aspect auto focal center principal point near far curve clip width height density edge tear compute normals metallic roughness opacity rot", "Unprojects a 2D depth map and optional color image into a 3D point cloud or triangulated surface mesh, supporting pinhole camera, planar, radial and cylindrical projections with depth curves and edge tearing." },
      { "Difference", "3D", "merge union intersect difference material from inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "Boolean difference: subtracts every input after the first from the first, like a cookie cutter. Needs closed, manifold input." },
      { "Disc", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner radius p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A flat filled circle/disc mesh (as opposed to Cylinder, which has height)." },
      { "Displacement", "3D", "scalar along normal vector rgb xyz strength frequency midlevel source texture noise octaves roughness affects flat shade flip normals inherit selection only color metallic opacity shading emission ior transmission specular clearcoat subsurface radius curl flow geo", "Moves a geometry's vertices, or a cloud's points, by a texture or by 3D noise. Texture: luminance pushes along the normals, or RGB moves in XYZ. Noise: Smooth, Fractal, Curl (swirling flow), Ridged or Cells, animated with the transport; on points it can tint or resize them instead of moving them." },
      { "Distribute Points in Grid", "3D", "count spacing jitter point tint", "Generates a flat rectangular lattice of points from nothing - no geometry input. Count X/Y and Spacing X/Y set the grid, Jitter randomises each point off its cell centre. Ordering matches Image to Points exactly (row-major, cell-centre UV), so a grid and an Image to Points at the same counts line up point-for-point." },
      { "Distribute Points on Faces", "3D", "density method random poisson disk min distance point inherit material color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "Scatters points across the input mesh's surface, area-weighted so large faces get proportionally more - even coverage, unlike Mesh to Points, which walks the vertex list and therefore clumps wherever the topology does (a UV Sphere's poles). Density sets how many; 'method' chooses plain Random or Poisson (blue-noise, honouring Min Distance so no two points crowd together)." },
      { "Dodecahedron", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A 12-faced platonic solid." },
      { "Draw", "Source", "loop replay playback play brush soft round hard square spray chalk ink bleed opacity hardness spacing jitter eraser color canvas width height recording clear rec strokes", "Paint straight onto the node preview. Six procedural brushes, eraser, spacing and jitter. Patch an image in to paint over it. Record, then draw - replaying redraws the stroke in time, and the canvas size follows the input when one is patched in." },
      { "Drift", "Prediction", "stray momentum link frozen profile anchors follow leader node index param section conditioned recall bar quantize rate smoothing smoothness range override lo hi depth", "Learns where you leave each knob and how fast you move it, then keeps the knob going after you let go, settles it into your usual places and wanders between them at your pace. Speed scales the learned pace, Stray widens or narrows the wandering, Momentum is how long a release carries on, Link lets your live hand activity stir it: quiet knobs wake up while you play and settle when you stop. Shift-drag a driven knob to take over; the dot on the knob shows how much history backs it and the faint marks show where it is likely to go next. Freeze stores the learned profile in the patch." },
      { "Drive", "AudioEffects", "drive bias tone color audio", "A tanh saturator: drive (0-40dB into the shaper), bias (asymmetry - the difference between fuzzy and warm), tone (bipolar tilt after the shaper) and output trim. A DC blocker always runs since bias otherwise leaks a constant offset." },
      { "Drum Sequencer", "Synths", "lane0 path pan pitch fine tune finetune decay transient mute solo choke lane accent vol start end step0 step1 step2 step3 step4 step5 step6 step7 step8 step9 step10 step11 step12 step13 step14 step15 step16 step17 step18 step19 step20 step21 step22 step23 step24 step25 step26 step27 step28 step29 step30 step31 lane1 lane2 lane3 lane4 lane5 lane6 lane7 rate bars bar 2t 4t 8t 16t 32t fix steps swing run pattern name part global category pick groove stop randomise clear", "An 8-lane, up-to-32-step drum machine: 8 lane cards (waveform + transient/decay/pitch/fine tune/volume/pan) above an 8-lane step grid that shows 16 steps at a time (the small 1-16 | 17-32 pill at the right of the line under it switches pages once steps goes past 16 - greyed out until then; a dot marks the page the playhead is on). Click a card's waveform to load its sample (a drag from the Samples panel or an OS file drop also work), or drag its edge handles to trim the playback range; x clears it, and the choke button cycles its choke group (0 = none - two lanes sharing a group cut each other off, the closed/open hi-hat case). In the grid, R randomises that lane's fill, M/S mute or solo it. Click a step to toggle it, drag vertically on a lit step to set its velocity, drag horizontally to paint a run of steps on/off. Between the lane cards and the grid, the groove picker holds a built-in library of 141 grooves in 10 categories: pick a category (jumps to its first groove) or a groove (the list is grouped and has a filter box), step through with < and >, and switch the groove's A verse / B bridge / C chorus part with the small A B C pill at the end of the row; picking replaces the pattern, rate, swing and step count in one undo step and fills any empty lane from the bundled kit (a lane you loaded yourself is never touched). The bottom rows are pattern-wide: rate/steps/swing/output, then four offsets (transient/decay/pitch/pan) composed on top of every lane's own value. Plays the moment it's patched, phase-locked to the transport - there's no note input, just its own Transport-derived sequence. run stops this node's own step firing without touching the transport; randomise seeds a musical kick/snare/hat starting pattern. A .mid file can become the pattern: drop it on the node, or keep .mid files in the My grooves folder (the last category in the groove picker, whose last row opens the folder). Its first two bars are placed on a 1/16 grid as 16 or 32 steps - General MIDI drum notes go to the matching lanes, and a melodic file gives its 8 lowest pitches to lanes 1-8 - at rate 1/16 with no swing, and the pattern takes the file's name." },
      { "Dynamics", "AudioEffects", "threshold ratio attack release makeup detector rms sidechain external analog sc hpf style clean bus audio", "A compressor: style, threshold, ratio, attack, release, makeup, a peak/RMS detector switch, and a sidechain switch that feeds the detector from the second input pin instead of the main signal. Style picks the character: clean (exact, a 6 dB knee), bus (VCA glue: the release waits until the attack lets go, a 10 dB knee), opto (a light cell: slow to catch small peaks, a fast then slow release, an 18 dB knee) or FET (the detector hears the output, so it grabs fast, a 2 dB knee). Warm adds transformers either side and rolls the top off as the gain comes down. The graph shows the static transfer curve - input dB in, output dB out." },
      { "EQ", "AudioEffects", "band1type band freq band1freq band1q band1gain band1on band2type band2freq band2q band2gain band2on band3type band3freq band3q band3gain band3on band4type band4freq band4q band4gain band4on band5type band5freq band5q band5gain band5on db selected low shelf peak audio", "Five fixed bands (low shelf, three peaks, high shelf by default), each switchable to any of low shelf/peak/high shelf/hp 12/lp 12 and independently on or off. Drag a band's dot on the curve to set its frequency and gain, Shift-drag to set Q, double-click the dot to bypass that band - the knob row below always follows whichever band you last touched." },
      { "Edit Mesh", "3D", "ops open 3d view geo", "Holds Edit Mode edits made in the 3D View: press Open in 3D View, or select the item and press Tab. 1/2/3 pick points, edges or faces; G, R and S move, rotate and scale the selection; E extrudes, I insets, X deletes. The edits replay on the input, so they follow an upstream change that keeps the shape in place: raise a Cube's detail and a picked face stays the whole face, a moved point stays a smooth bump of the same reach. A selection with nothing near it is skipped and the node warns." },
      { "Ellipse", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A filled/stroked ellipse - Aspect stretches it from a circle." },
      { "Envelope", "Modulators", "attack ms decay sustain release constant threshold centred adsr maths hold curve per voice", "Applies an ADSR contour to an incoming modulator instead of generating its own trigger: rising above threshold starts attack/decay/sustain, falling back below it starts release. Patch an LFO in and its swing gets shaped by the ADSR, retriggering once per LFO cycle. Output 'ADSR' is the envelope itself, 0 at rest up to 1 at the peak, with stage times exact at any frame rate. Output 'centred' (what older patches load with) collapses toward 0.5 as the level falls, so at level 0 the input has no say and at level 1 it passes through. Hold keeps the peak before decay; each curve bends its stage (positive falls fast first, like an analog envelope). With 'per voice' on and the ADSR output cabled straight into an Analog or Wavetable knob, every note runs its own envelope, gated by its own note-on and note-off." },
      { "Equation Synth", "Synths", "vel curve formula eq preset sine pure additive harmonics chebyshev t3 t4 t5 phase distortion fm sinc pulse dirichlet exponential chirp weierstrass fractal tanh soft saturator width morph formant vowel peak fold tangent warp sawtooth dom domain normalized pi angular bipolar knob pan frequency octave semi fine glide unison detune stereo attack amp decay sustain release filter lp hp bp notch comb cutoff reso resonance drive oct notes", "A synth defined by a live formula (y = f(x, a, b, c, d, t)) instead of a fixed waveform - knobs a-d feed the equation directly, so turning them reshapes the waveform itself rather than modulating a preset one." },
      { "Explode", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by faces loose parts iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Pushes each face outward from the mesh's centre along its own normal, by Amount, randomized per-face by Seed." },
      { "Extrude", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels move thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Extrudes every face of the input mesh along its own normal by Distance, with Inset shrinking each face first." },
      { "Extrude Selected", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Extrudes only the faces marked by an upstream Select op along their own normals, by Distance, with Inset." },
      { "FM", "Synths", "algorithm feedback ratio ratio1 fixed fixed1 freq1 level1 attack attack1 decay decay1 sustain sustain1 release release1 ratio2 fixed2 freq2 level2 attack2 decay2 sustain2 release2 ratio3 fixed3 freq3 level3 attack3 decay3 sustain3 release3 ratio4 fixed4 freq4 level4 attack4 decay4 sustain4 release4 notes", "A 4-operator FM synth: four sine operators wired by one of 11 algorithms, from a 4>3>2>1 stack to four carriers side by side. Each operator follows the note at a ratio, or sits at a fixed frequency, and has its own level and ADSR; a carrier's level is how loud it is, a modulator's is how far it bends what it feeds. Feedback lets operator 4 modulate itself, from a brighter sine to a buzz. 8 voices, note-driven, rendered at 8x so high notes stay clean." },
      { "Face Track", "Modulators", "mirror smoothing hold ms present head yaw pitch roll eye brows mouth smile gaze", "Tracks one face from an image or camera wire: head position, turn, nod and tilt, each eye open or closed, brows, mouth open, smile, and where the eyes look. A small preview shows what is tracked. Needs the Tracking pack (Settings > Extensions)." },
      { "Feedback", "Compositing", "delay frames", "Outputs the previous frame - a one-frame delay, not an effect. It only does something visible inside a loop: patch a downstream node's output back into a Feedback node's input, then use that Feedback output upstream, without the graph recursing. See Menu > Help > 'Using Feedback' for the full patch." },
      { "Feedback 3D", "3D", "loop", "A one-frame delay for geometry, so a chain can loop back on itself. Patch the start shape into seed and the end of the chain into loop: every frame it outputs what the loop made from the frame before - growth, drifting clouds, home-made particle sims. It restarts from the seed on a rewind, holds while the transport is paused, and resets if the loop blows up to infinity. Reset starts over from the seed; with nothing in loop it passes the seed through." },
      { "Field Effect", "AudioEffects", "code expose rms field next param map drive tone bias pins tube overdrive save export import edit", "Runs a Field kernel once per audio sample, on the audio thread - write your own sample-domain audio effect. `in` is the audio input pin, `state` declares per-voice memory, `param` exposes a modulatable knob. `reduce.rms(in, loHz, hiHz)` publishes a band-limited RMS meter reading once per block." },
      { "Field Graph", "Utility", "code uid add encapsulated ownership text field next param map synth effects voice save export import edit regenerate unpack canvas", "Runs a Field kernel once, at edit time, to build part of the graph itself - emit(\"Type Name\", k0, k1, ...) spawns a node and hands back a handle, connect()/set()/place() wire it up, set its params and position it. Press Regenerate to re-run: it diffs against what it built last time (by emit-site identity) instead of deleting and respawning, so hand-edits to params on the spawned nodes survive an unrelated Regenerate." },
      { "Field Modifier", "3D", "code max elements generate count publish scalar field next param map amp freq pins wave displace save export import edit geo", "Runs a per-vertex Field kernel over geometry, modifying P, N, uv, Cd and custom attributes with rate-inferred execution. It also runs over point clouds (compiled to GLSL when the input has GPU points), where life is available as an attribute; the point presets include Limit to Box and Project onto Shape." },
      { "Field Notes", "Notes", "code root field next param map hits euclidean save export import edit notes", "A note node whose body is a Field script. The script runs per sample against the transport beat; note(pitch, vel, len) inside an if sends a note out (len in beats, 0 holds as long as the incoming note). tick(div) fires on each beat division, deg(d) is a scale degree under Root/Scale, rand() is 0..1. Wire it into any synth or MIDI-out." },
      { "Field Primitive", "3D", "code count max elements topology points plane grid sphere cylinder torus disc publish scalar field next param map height freq pins solid terrain save export import edit", "Generates procedural 3D point geometry from scratch using a per-element Field kernel (Circle, Spiral, Grid Lattice, Fibonacci Sphere, Helix, Torus Knot)." },
      { "Field Synth", "Synths", "code voices max expose rms field next param map detune cutoff res sub warmth attack pins dual oscillator pad save export import edit notes", "A polyphonic synthesizer whose voice is a Field kernel you write yourself, compiled to a sample-domain register machine - the note-driven counterpart of Field Effect. `state` declares per-voice memory, `param` exposes a modulatable knob, and the kernel runs once per sample per voice, on the audio thread. maxVoices caps the polyphony; presets are complete starting kernels." },
      { "FieldPixel", "Source", "code width height animate expose state texture aux field next param map pins default uv gradient save export import edit", "Runs a Field kernel once per output pixel, on the GPU - write your own image generator or effect in Field instead of GLSL. `state` declares persistent per-pixel memory that survives to the next frame (which is what makes reaction-diffusion and trail effects expressible here), `param` exposes a modulatable knob, and extra input/output image pins can be declared by the kernel. width/height set the output resolution; presets are complete starting kernels." },
      { "Fit", "Compositing", "fit fill stretch native width height match res offset bg color opacity", "Resamples an input to a chosen resolution. Fit letterboxes, Fill crops, Stretch ignores aspect, Native passes through. Offset X/Y slides the result in output pixels (+ right, + up). Use it to make differently-sized sources composite predictably." },
      { "Flanger", "AudioEffects", "delay depth feedback rate div analog spread audio", "One short modulated delay line with feedback - the jet-swoosh comb filter. Feedback past zero flips the comb's polarity for a hollower sound; the right channel reads a quarter-cycle ahead of the left for width." },
      { "Fluid", "Compositing", "resolution full half quarter pressure iterations viscosity damping velocity swirl vorticity dye fade image refresh force stirrer orbit pulse spin strength view obstacles", "A 2D fluid simulation that carries the input picture along as dye, so it smears, swirls and folds. Patch a motion image (Optical Flow) into force to push it, and a picture into obstacles: bright areas are solid. The stirrer (Orbit, Pulse, Spin) moves it with nothing patched. Resolution divides the simulation size; Reset clears it." },
      { "Formant Filter", "AudioEffects", "vowel audio", "Three parallel bandpass resonators tuned to a vowel's formants (F1/F2/F3), morphed continuously A-E-I-O-U by the vowel knob - a vocal-tract-shaped filter for any input, not just voice." },
      { "Formula", "Source", "formula width height knob animate buffers st image buf common st0 st1 st2 st3 st4 st5 st6 st7 names circle default save export import edit glsl", "A live GLSL shader. Pick a preset or press 'Edit GLSL...' to write your own; four knobs (uA-uD) are exposed for modulation." },
      { "Frequency Shifter", "AudioEffects", "shift feedback spread range analog fine wide 10k audio", "A true single-sideband frequency shifter: moves every partial by the same number of Hz rather than multiplying frequencies (Pitch Shifter) or producing sum/difference pairs (Ring Mod) - destroying harmonic relationships for classic metallic and inharmonic textures, or rising/falling barber-pole spirals with feedback." },
      { "Gain", "Utility", "db audio", "A single gain stage in dB, with a level meter - the simplest audio utility there is. Reach for it to trim a source before a Mixer, or to set up a clean level for something that has no output volume of its own." },
      { "Gate", "Notes", "hold ms notes", "Overrides how long a note sounds: holdMs schedules the note-off that many ms after note-on instead of passing the real one through, for a fixed duration regardless of how long the key was held. 0 = passthrough (off)." },
      { "Gear", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A cogwheel silhouette - Sides sets tooth count." },
      { "Gear 3D", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides depth bevel segments tooth super n2 hub hole n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A 3D cogwheel - 'depth' sets tooth depth, 'tooth depth'/'hub hole' shape the teeth and centre bore. Named with a '3D' suffix because the 2D Shape node already has its own 'Gear'." },
      { "Generate Samples", "Synths", "path pitch finetune start end decay fade loop rate fix reverse pingpong card variation gen bars bar follow transport part tone energy space mood keep generated version synths generate export wav tempo rev cancel pads plucks notes", "Makes a sample instead of loading one. Pick a music style (deep house, dub techno, lofi beats and 31 more), a seed and a length of 1, 2, 4 or 8 bars, and press generate: a private patch built from that style - drums, bass, chords, a motif, each through its own synths and effects - renders a seamless loop on a background thread while the canvas keeps running. part picks the whole mix (all) or one layer of it from the same seed: synths (bass and the motif line), pads (the chords held on a slow-swelling voice), plucks (the chords arpeggiated on a short plucked voice), percussion (clap, toms, bell) or drums (kick, snare, hats). variation is how far each node strays from its defaults; the dice picks a new seed. follow transport makes the loop at the patch tempo, key and scale, card's own at the style's. The status line names what was made, its tempo, key and scale. Every loop comes out at -14 LUFS under a -1 dB true-peak ceiling; a seed that renders silent or broken is redrawn up to three times before the node says so. Changing a setting marks the sample stale until you generate again. The patch saves the recipe, not the audio, and renders it again when reopened; keep as file writes the loop to a wav, and from then on it is saved as that file. Playback is the sample player's: drag the waveform edges for start and end, pitch, gain and loop below it, and connect notes to play it from a keyboard." },
      { "Geometry", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "The base 3D primitive node - pick any of its 24 shapes from the dropdown. Each shape also has its own directly-spawnable named node (Cube, Sphere, Torus, ...) that just starts on that shape." },
      { "Geometry Table", "Modulators", "sample vertex scatter contour rows sort distance angle offset space fixed bounds smooth extent slice axis geo cx cy cz spread x1 y1 z1 x2 y2 z2 x3 y3 z3 x4 y4 z4", "Samples up to 16 points off a patched geometry source and outputs each as its own X/Y/Z modulator, plus a centroid (cx/cy/cz) and spread aggregate that stay meaningful however the row count or point set changes. Vertex mode reads native vertices (or a point cloud's points, which always wins over its own billboard mesh); Scatter reads an area-weighted random sample instead; Contour walks the mesh's boundary/slice outline (or a patched curve) in order. Sort turns the table into something specific - by axis for a ramp bank, by angle for a phase-ordered ring, by distance from the centre. offset scrubs a read head across the sampled set without re-sampling, so it's the one control worth binding to an LFO. Fixed space maps world units through `extent` (how far the object may travel, not how big it is); Bounds self-scales to the sampled set's own bounding box, which means a rigid translation of the source produces no change - that's by design, not a bug." },
      { "Glide", "Notes", "glide ms notes", "Plays a fast chromatic run between a note and the next one as an approximation of portamento (NoteEvent has no continuous pitch, so this is a glissando, not a true pitch ramp)." },
      { "Grain Molder", "Synths", "path grain gm key bright random order descending ascending pitch decay start end loop rate fix reverse pingpong load record audition rev notes", "Slices audio into overlapping grains, calculates per-grain metrics (Level, Brightness, Random), and rearranges them based on a continuous blend between original temporal position and metric rank. At amount 0 it is the clean identity passthrough; at 1 it is fully sorted into a swell or brightness contour. Rendering runs asynchronously on a worker thread." },
      { "Granular", "Synths", "file path scan grain length density freeze spray random rnd pitch pan spread reverse prob shift finetune fine tune gran shape window hann gaussian triangle exp decay trapezoid width start end loop load record", "A granular synthesizer: it dissects a loaded sample (or audio recorded through its own 'record in' pin) into micro-grains and re-emits them - grain length and density set the texture, position/scan set where in the sample the grain cloud reads from, and freeze pins it there. The four random controls (position spray, length, pitch, pan) plus reverse probability are what turn a sample into a cloud rather than a stutter. Drag the waveform's edge handles to trim start/end; the grain dots on the display are the live emission." },
      { "Group", "Compositing", "label width height color", "Created with {mod}+G on a selection, not spawned from the palette. Sizes itself automatically to fit its members - drag a node in to grow the box, drag one out to shrink it. Drag anywhere inside the box to move the whole group; right-click > Ungroup (or {mod}+U, {mod}+Shift+G) dissolves it, leaving members in place (or ungroup one member from its own context menu)." },
      { "Group 3D", "3D", "geo", "Carries up to eight geometry inputs through one pin into Render 3D (or into another Group 3D), so a scene is not limited to Render 3D's four geometry pins. Nothing is merged: each input keeps its own material, texture, mapping and transform. Anything else downstream, like Transform or Join Geometry, receives the inputs merged into one mesh, each placed where Render 3D would draw it; that merged copy keeps tints as vertex colour but not per-input materials." },
      { "HDRI", "3D", "path intensity rotation sun threshold angle shadow res filter choose hdri", "Loads an equirectangular .hdr or .exr image and patches into Render 3D's env input, replacing the fixed sky gradient with a real image for the background and for reflections/ambient light. Rotation turns the image around Y; intensity scales it independently of Render 3D's own env intensity. Reflections use the image's own mip chain scaled by roughness as a cheap stand-in for a proper blurred prefilter - very glossy metal will read a little softer than a full IBL renderer would give it. Use this node rather than Image Source for HDRIs - Image Source clamps to 8-bit sRGB, which throws away exactly the above-1.0 highlight range an HDRI needs." },
      { "Hand Track", "Modulators", "mirror smoothing hold ms present palm index thumb pinch open roll fist point peace thumbs up ok rock", "Tracks one hand from an image or camera wire and turns it into modulators: palm and fingertip position, pinch, open, roll and size, plus six gestures (fist, point, peace, thumbs up, ok, rock) that read 1 while you make them. A small preview shows what is tracked. Needs the Tracking pack (Settings > Extensions)." },
      { "Heart", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A heart-shaped outline." },
      { "Helix", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides wire turns height bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A helical tube spiraling around an axis - 'tube' sets the tube's radius." },
      { "Hexagon", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A six-sided regular polygon (a Polygon preset with Sides fixed to 6)." },
      { "Humanizer", "Notes", "hu time timing ms vel velocity pct notes", "Adds small random offsets to incoming note timing and velocity, so a mechanically even sequence sounds played by hand instead of quantized." },
      { "Icosphere", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A sphere built from subdivided triangles (an icosahedron refined outward) - more even triangle distribution than a UV Sphere." },
      { "Image Analyze", "Modulators", "sample global average point probe region interest center weighted radius operation math op custom expression red green blue alpha luminance sum product max min range saturation hue euclidean norm delta motion formula offset power invert clamp clamp01 smoothing samples sec rate res result bright contrast sat cx cy", "Turns an image or video into control values and modulation channels. Supports UV point probes, ROI boxes, 22 math/color operations, custom algebraic formulas, and multiple modulation output taps." },
      { "Image Source", "Source", "path choose image", "Loads a still image. Opens the native file picker and decodes anything macOS can read - PNG, JPEG, TIFF, HEIC, RAW and more." },
      { "Image to Points", "3D", "density width height from depth source luminance red alpha flat point threshold use image colour color tint luma", "Converts an image into a 3D point cloud - brightness/depth-source drives per-point depth, with density, threshold, point size and optional colour-from-image." },
      { "Inset", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments move angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Shrinks each face region inward by 'width' and raises it by 'depth' (negative sinks it), with a wall around it. Works on the Select marked faces, or on all faces with selection-only off." },
      { "Instance on Points", "3D", "points from point vertices edges faces max instance random rotation align normal offset inherit material color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius shape cloud", "Stamps a shape at every point, drawn in one instanced call. The points pin takes a mesh to sample (the Points, Edges or Faces sampler nodes), and shape is the geometry stamped at each point. The optional cloud pin takes a point cloud (Particle System, Image to Points, Mesh to Points, a Model 3D .ply) and replaces the sampling: every point gets a copy, coloured by the point, and a GPU cloud stays on the GPU. Shape is always needed; points is needed only when nothing is in cloud. Any node chained after this one operates on the shape being stamped, once, not on the realized scatter - except Transform, which moves the whole scatter as one rigid group." },
      { "Intersect", "3D", "merge union intersect difference material from inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "Boolean intersection: keeps only the volume where all the closed, manifold input solids overlap." },
      { "Invert", "Modulators", "no cable constant low high", "Mirrors a modulator around the midpoint of a low/high window, so what was at the top of the range lands at the bottom. Deliberately not a flat 1-v, which is why it still does the right thing when fed something already outside 0..1 - an unclamped Math output, for instance." },
      { "Join Geometry", "3D", "merge union intersect difference material from inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "Combines two or more geometry inputs into one. The boolean modes (Union, Difference, Intersection, etc, each also spawnable as its own named node) need closed, manifold solids to produce a clean result - open surfaces can give garbage." },
      { "Key-Snap", "AudioEffects", "snap glide root global key major natural minor audio", "Moves every spectral peak of the sound to the nearest note of a scale, so chords and layered sources stay in key. Snap blends between untouched and fully in tune, glide sets how fast a peak slides to its new note, and global key follows the transport's key and scale. Latency is 42.7 ms (2048 samples)." },
      { "Keyboard", "Notes", "octave base transpose velocity numpad computer keyboard use global", "A hardware-free note source: click-and-drag the on-screen piano, or hover the node (or select it alone) and type on your laptop keyboard (Logic/GarageBand's Musical Typing layout - ZXCVBNM... is one octave, QWERTY... the octave above) to test a patch with no MIDI controller at all." },
      { "Klein Bottle", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A non-orientable closed surface - the classic self-intersecting 'bottle with no inside or outside'." },
      { "L-System", "3D", "axiom rules generations iterations angle length branch radius sides taper color metallic roughness opacity shading emission", "Grows a plant or fractal from text. Type an axiom (the starting string) and rewrite rules such as X=F+[[X]-X]-F[-FX]+X;F=FF (separate rules with a semicolon), set the angle and the number of generations, and a 3D turtle draws it: F draws forward, f moves without drawing, + and - turn, & and ^ pitch, \\ and / roll, | turns around, [ and ] start and end a branch. Length and radius shrink on each branch by the scale controls. The result is a tube mesh and a curve a Path can follow, and the same text always grows the same shape." },
      { "LFO", "Modulators", "shape sine triangle saw up down square sample hold rate beats phase low high hz from transport retrigger maths per voice bar trig", "Sine, triangle, saw up/down, square and seeded sample-and-hold. Rate as a synced division, free beats or Hz; phase from the transport, free-running, or restarted by the trig input; plus phase and an output range." },
      { "Layer Stack", "Compositing", "linear light headroom fit stretch fill blend fix mode0 normal darken multiply color burn darker lighten screen dodge add lighter overlay soft hard vivid pin difference exclusion subtract divide hue saturation luminosity average negation reflect glow erase anti opacity opacity0 mode1 opacity1 mode2 opacity2 mode3 opacity3", "Four inputs stacked bottom-up: A is the base, D sits on top. Each layer has its own blend mode and opacity, and dragging a layer header reorders the whole layer." },
      { "Light", "3D", "directional point sun ambient spot area orbit azimuth elevation distance color intensity falloff cone angle penumbra beat per width height normalize diffuse specular transmission soft cast shadow radius filter res clip temperature use kelvin exposure cutoff", "A light source for the 3D scene. Render 3D takes up to 3 lights - patch more in and only the first 3 are used." },
      { "Limiter", "AudioEffects", "threshold release audio", "A brickwall limiter: nothing passes above threshold. In gain drives the signal into it, release sets how fast it lets go, out gain sets the final level, and the meter shows the gain reduction. Always fully wet." },
      { "Line", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner thick radius sides inner ratio rotation fill color opacity stroke feather bg", "A straight stroked line, without a fill interior." },
      { "Looper", "Synths", "take bars bar 2t 4t 8t 16t 32t start thru finetune pitch fade loop file rec play dub clear undo audio", "How to use: wire the sound to loop into the input and the out to Audio Out, press Rec (with the transport playing and sync on it waits for the next bar; pressed up to 200 ms late, the take still starts on the line just passed), and the take ends by itself after the take length, then loops; Play stops and restarts it, Dub layers what comes in over it, Clear empties it. The waveform shows the loop with a playhead and the beat grid, and the line under the title says what the looper is doing. Each button has a CV pin, so a footswitch or MIDI note can drive them (a rising edge presses). take sets the length: a musical division (1 bar by default), or free, where the next Rec press ends it. Pressing Dub while recording ends the take and goes straight into overdub. Undo steps back one layer at a time (the last take, overdub or Clear, up to 8 steps) and the loop keeps playing; pressed during an overdub it throws that layer away. Playback has the Sampler's controls: finetune (cents), pitch (semitones), speed (negative plays backwards), volume, and fade in / fade out (ms) at the start and end of every pass. At exactly 1.00x the loop stays on the grid; at any other rate it plays in length / rate and DRIFTS against the transport, and Dub is paused while it does (layers are only written at the rate they were recorded). thru monitors the live input. Each take is always shifted by the audio interface's measured round-trip latency, so a loop played in time sits on the grid. The loop (up to 60 s) is saved as a WAV in your Recordings folder and comes back, stopped, when the patch is opened." },
      { "MIDI CC", "Modulators", "device channel controller is note low high invert", "Binds one physical control on a MIDI controller - a knob, fader or pad - and reports its position as a modulator. Press Learn and move the control; the node remembers that channel + controller number and polls only that binding. low/high remap the output range and invert flips it. Works with any class-compliant USB MIDI controller, since it only ever reads generic Control Change / Note On messages. You rarely need to add this node by hand: right-click any parameter, choose MIDI learn, and move a control - this node is created (or reused if that control already has one) and bound to the parameter over its full range. Only one MIDI learn runs at a time; starting another cancels the first, and Esc cancels." },
      { "MIDI File", "Notes", "path transpose loop vel velocity use global load", "Plays a Standard MIDI File as a note source. Load a .mid (or drop one on the canvas) and it follows the transport: play, stop and seek move the playhead through the file, and the project tempo rules - the file's own tempo is ignored. transpose shifts every note, position (0 to 1 across the file) is where playback starts - it restarts from there whenever the transport starts or seeks, and jumps there when you move the knob. speed 1 follows the project bpm and scales it from there (the file's own tempo is ignored - it is just notes). vel scales every velocity, and loop repeats the file, rounded up to a whole 4/4 bar. Drum-channel (10) notes are never transposed. Format 0/1/2, SMPTE-timed (mapped at 2 beats per second) and RMID-wrapped files load; pitch bend and CCs are not played. The Global Scale button snaps every played note, after transpose, to the project key and scale; drum-channel notes never snap." },
      { "MIDI Notes", "Notes", "channel device transpose velocity use global mpe bend range", "Reads note events from a connected MIDI input device and outputs them as a note cable - the entry point for playing a synth or sampler from an external keyboard/controller. Turn on mpe for an MPE controller (Seaboard, Osmose, Linnstrument): each held note follows its own pitch bend. Pick the input device it listens to, or leave it on all inputs; Learn takes the device and channel from the next key you play." },
      { "MIDI Out", "Utility", "device channel offset ms clock cc1on cc1 cc1num cc1val cc2on cc2 cc2num cc2val cc3on cc3 cc3num cc3val cc4on cc4 cc4num cc4val panic notes", "Plays a hardware MIDI synth from a note cable. Pick the device and the channel (1-16); notes sent here do not reach Audio Out, so the synth makes its own sound. Four CC rows send a controller number and a modulatable value, only when it changes, so any LFO or macro can turn a knob on the synth. 'clock' makes Infinite the master clock (24 pulses per beat, with Start, Stop, Continue and song position) and switches itself off while Infinite follows an incoming clock. 'offset' shifts everything by -50 to +50 ms to line up with the synth's latency. Every note still held is released when you delete or bypass the node, change device, stop the transport or press panic. Pick \"Infinite (virtual)\" to publish a source called Infinite that DAWs and other apps list as a MIDI input." },
      { "MIDI Trigger", "Modulators", "device channel note hold velocity sensitive", "The pad counterpart of MIDI CC: it fires a decaying 0..1 pulse whenever one specific MIDI note is hit, then sits at 0. A pad hit is an event rather than a position, so this spikes and decays over 'hold' seconds the way Audio Analyze's onset output does, instead of holding a live value. Velocity sensitivity scales the spike by how hard the pad was struck." },
      { "MPC", "Synths", "pad0 path pad pitch pan fine tune fade fadein fadeout div pad1 one shot gate loop rate bars bar 2t 4t 8t 16t 32t pad2 pad3 pad4 pad5 pad6 pad7 pad8 pad9 pad10 pad11 pad12 pad13 pad14 pad15 selected load folder clear notes", "How to use: wire the out into Audio Out, drop audio files onto the pads (or click an empty pad, or Load... / Folder... for the first 16 files of a folder), then click a pad or send notes into the notes input - notes 36 to 51 play pads 1 to 16. A 16-pad sample player: pad 1 is bottom-left like a hardware MPC, every pad is a square tile showing its waveform, number and mode, and each pad has its own CV pin, so a MIDI CC / Note modulator or any gate can play it. Every pad is its own voice, so pads play together, and a click plays at once. A hit follows the pad's mode: one shot plays the whole sample and a new hit restarts it; gate plays while held (mouse down, CV high or note held) and stops on release; loop toggles a looping playback on each hit. Click selects a pad (right-click selects without playing); the rows below the pads edit the selected pad: sync and rate, fine tune (cents), pitch (semitones), speed (negative plays backwards), volume, pan, mode, and fade in / fade out (ms, at the start and end of every pass), defined as on the Sampler. sync is per pad: Free (the default) plays a hit at once; Synced latches the hit and fires it on the next grid line of the transport at the chosen rate (1/4, 1/8, 1 bar ... the same divisions as every other node), sample-accurately; a hit on the line itself fires on it, with the transport stopped it fires at once, and in gate mode letting go before the line cancels the hit. In loop mode a synced pad re-triggers the sample on every division while it is on (one pass per division: a longer sample is cut at the line, a shorter one leaves a gap), and with the transport stopped it plays as a plain loop. The rate control is greyed while a pad is Free. Every param of every pad can be modulated at any time: a cable stays bound to its own pad when you select another pad, and an orange dot on a tile shows that pad has a modulated param. A tile shows the mode and, when synced, the rate. The node's audio out is the mix of all pads. Loaded sample paths and pad settings are saved with the patch; the audio is re-read on load." },
      { "MSEG", "Modulators", "rate beats hz loop start end per voice points bar trig", "A shape you draw, played over time. Click empty space to add a point, drag to move it, right-click to remove it; the small ring on each segment bends it. rate is how long one pass takes (beats, a synced division, or Hz). With nothing patched to trig it follows the transport. A trig cable starts the shape on each rising edge: loop off plays it once and holds the last value; loop on repeats the part between loop start and loop end while trig stays high and plays on to the end when it drops. Loop start = loop end is a sustain point." },
      { "Macro Bipolar Knob", "Macros", "pan detent label", "A centre-detent knob running -1 to +1, exposed as a modulator - the right control for anything that has a natural middle (pan, detune, tilt). Its 0..1 output puts the detent at exactly 0.5, which is also where a bipolar modulation binding reads as 'no modulation'." },
      { "Macro Knob", "Macros", "macro label", "A single named slider (0-1, with a response curve and invert) meant to be patched out to several other sliders at once - one control that fans out to many parameters." },
      { "Macro NumBox", "Macros", "min val max step label", "A number box with drag-to-scrub and direct typing, over a range and step you set yourself - for when the value matters as a number (a count, a Hz figure, a bar length) and a 0..1 slider would be the wrong instrument." },
      { "Macro Radio Selector", "Macros", "selected count label", "A multiple-choice selector emitting one discrete step per option - the control to use for a dropdown-shaped parameter (a mode, a waveform, a preset index), where a continuous slider would land between valid values. 'count' sets how many options." },
      { "Macro Slider", "Macros", "slider label", "A named fader exposed as a modulator - drag its output onto any slider's modulation pin to drive that parameter by hand. The plain 0..1 member of the Macro family; use Macro Knob when you want a response curve and invert as well." },
      { "Macro Step Gate", "Macros", "pattern rate beats label", "An 8-step gate that advances on the transport at rateBeats - a rhythm you draw rather than a curve. The output is the current step's on/off state, so it is the Macro family's answer to 'make this parameter pulse in time' without wiring an LFO and a Compare." },
      { "Macro Toggle", "Macros", "state label", "A latching on/off switch exposed as a modulator: output is exactly 0.0 or 1.0, nothing in between. Useful for driving a mode/enable parameter, or for gating another modulator through a Math node's multiply." },
      { "Macro Trigger", "Macros", "pressed label bang", "A momentary pad: output is 1.0 while pressed and 0.0 the moment it is released, with a visible flash on the press. Reach for it to fire something that responds to an edge - a Feedback burst, an envelope, a Resynthesize step - rather than to hold a value." },
      { "Macro XY", "Macros", "pad loop path rec play clear", "A 2D pad exposing X and Y as two separate modulator outputs from one drag. The pad's path can be recorded, looped and replayed in time, like Resynthesize's orb." },
      { "Mapping", "3D", "space uv generated object blend softness translate rotate triplanar geo", "Transforms the UV or 3D texture coordinates used by materials/textures downstream - translate, rotate and scale, independent of moving the geometry itself." },
      { "Material", "3D", "color metallic roughness opacity shading lit normals uv flat wrap clamp repeat mirror emission ior transmission trans rough specular clearcoat coat subsurface sss radius sheen iridescence irid thickness anisotropy aniso rotation dispersion alpha cutoff texture bump height map normal strength image geo albedo ao", "Applies shading, colour, metallic/roughness/opacity and emission to a geometry input, plus an optional normal map input (its strength slider only appears once something is patched into it)." },
      { "Math", "Modulators", "operation op min max average difference only no cable constant offset clamp", "Combines two modulators - add, subtract, multiply, divide, min, max, average, difference - with gain and offset. Unpatched inputs fall back to a constant, shown as an editable slider; a patched input just shows as 'patched'." },
      { "Merge by Distance", "3D", "threshold geo", "Welds vertices closer together than Threshold into one - the cleanup pass that makes a scatter or conversion result usable, closing seams a conversion left behind. Pushed to a large radius it collapses the geometry outright, which is sometimes the point." },
      { "Mesh to Edges", "3D", "sample vertices edges faces max points point weld seams dissolve angle degrees inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "Samples points along the input mesh's edges as a point cloud, for feeding Instance on Points or Metaballs." },
      { "Mesh to Faces", "3D", "sample vertices edges faces max points point weld seams dissolve angle degrees inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "Samples each face's centre point of the input mesh as a point cloud, for feeding Instance on Points or Metaballs." },
      { "Mesh to Points", "3D", "sample vertices edges faces max points point weld seams dissolve angle degrees inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "Samples the input mesh's vertices as a point cloud, for feeding Instance on Points, Metaballs, Displacement, Twist or Point Trails. Max points caps the count, point size sets how big each point draws, and weld seams counts a corner shared by several faces once." },
      { "Metaballs", "3D", "balls ball count resolution threshold bounds radius spread orbit beat spin max from cloud color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface", "Builds an isosurface (blobby, merging spheres) from a point cloud source, or from a manually-placed set of balls when no cloud is patched in." },
      { "Metallic", "Synths", "metal mat material steel bell bronze gong plate cast iron titanium glass crystal ceramic vibraphone bar transient decay stiffness freq frequency octave semi fine glide filter cutoff reso resonance drive width oct strike lp hp bp notes", "A physical-modelling synth for struck and plucked metal - bells, gongs, bars, plates, chimes, tines and strings - via extended Karplus-Strong waveguides and inharmonic modal resonator banks. 'material' picks the model, transient how hard it is struck, decay how long it rings, stiffness how inharmonic the partials are (which is what separates a bell from a string). Polyphonic with a note cable connected, free-running at 'frequency' when unpatched." },
      { "Mirror", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations plane weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Mirrors the mesh across a plane perpendicular to a chosen Axis, at a given plane offset. 'keep original' keeps the source geometry too, 'weld seam' merges the two halves where they meet." },
      { "Mixer", "Utility", "channels gain0 pan pan0 mute0 solo0 gain1 pan1 mute1 solo1 gain2 pan2 mute2 solo2 gain3 pan3 mute3 solo3 gain4 pan4 mute4 solo4 gain5 pan5 mute5 solo5 gain6 pan6 mute6 solo6 gain7 pan7 mute7 solo7 gain8 pan8 mute8 solo8 gain9 pan9 mute9 solo9 gain10 pan10 mute10 solo10 gain11 pan11 mute11 solo11", "The only node that sums audio - every other audio input pin takes exactly one cable, so any time two signals have to meet, they meet here. Four to eight slots, each with its own gain, pan, mute and solo, summed to one output." },
      { "Mobius Strip", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides width bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A one-sided, one-edge twisted strip - 'width' sets the strip's width." },
      { "Mod Curve", "Modulators", "no cable constant curve", "Remaps a modulator through a draggable transfer curve - click empty space to add a point, drag to move it, right-click to remove it (or right-click empty space to reset to a straight line). The gridline marks 0.5, where a bipolar binding's 'no modulation' point lives, and the moving dot shows where the input currently sits on the curve. mix blends between the raw input and the curved output, so 0 is a true bypass." },
      { "Mod Depth", "Modulators", "no cable constant depth", "Scales how much of a modulator's swing reaches its destination, without having to know anything about the destination. Because a modulation binding overrides the knob outright, 'depth' collapses the signal toward 0.5 rather than adding a fraction on top: at 0 the destination sits at its own mid-range and the modulator has no say, at 1 the source passes through unchanged. Negative depth inverts, so one knob covers how much and which direction." },
      { "Model 3D", "3D", "path part fit unit normalize recentre recenter rot spin point clip phase beats morph0 morph1 morph2 morph3 morph4 morph5 morph6 morph7 pose0 pose0x pose0y pose0z pose1 pose1x pose1y pose1z pose2 pose2x pose2y pose2z pose3 pose3x pose3y pose3z pose4 pose4x pose4y pose4z pose5 pose5x pose5y pose5z pose6 pose6x pose6y pose6z pose7 pose7x pose7y pose7z pose8 pose8x pose8y pose8z pose9 pose9x pose9y pose9z pose10 pose10x pose10y pose10z pose11 pose11x pose11y pose11z pose12 pose12x pose12y pose12z pose13 pose13x pose13y pose13z pose14 pose14x pose14y pose14z pose15 pose15x pose15y pose15z ik joint chain weight pole color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius open model texture", "Loads a 3D model file - obj, ply, stl, usd or usdz. A .ply with no faces (a scan, photogrammetry or a splat export) loads as a point cloud instead of a mesh, with its colours and normals: point size sets how big each point draws, and the points can go into Render 3D, the cloud pin of Instance on Points, or Displacement, Twist, Field Modifier and Point Trails." },
      { "Molder", "Synths", "path chaos pitch tone air snap stretch time start end loop rate fix reverse pingpong generation load record roll iterate rev", "Analysis/genome resynthesis: decomposes a loaded or recorded sample into tracked harmonic partials plus a real residual waveform, then Roll mutates a parameter genome and re-renders a new sample from it - each roll walks further from the last, not from the original. Iterate feeds the last render back in as the new source and re-analyses it (progressively eating the sound); Reset returns fully to the originally loaded/recorded sample - generation 0 and the six shaping knobs (tone/air/snap/stretch/time/pitch) back to neutral, and the analysis itself restored, undoing any Iterate. chaos sets how far the next roll jumps; pitch offsets on top of the genome's own pitch walk; tone balances partials against residual; air/snap are the residual's steady-hiss and transient-attack levels; stretch scales inharmonicity together with harmonic spacing; time warps the attack/decay timing without changing the sample's length. This is a sound designer, not a playable instrument - it takes no note input, only a single self-triggered voice with start/end range, loop, reverse and ping-pong, the same transport as Sampler. Analysis and rendering both run on a background thread, so rolling never stalls the UI. seed/gen/f0/harm in the readout are the exact genome (seed + generation count) and the analysed pitch - two integers are enough to reproduce any rolled sound exactly on reload." },
      { "Moves", "Prediction", "gesture fader1 fader2 fader3 fader4", "Your Moves macro faders: extracts the principal axes of your multi-knob gestures using PCA on deltas, letting a few macro faders drive many coupled parameters together in your style." },
      { "NDI In", "Utility", "source name", "Receives any NDI video source on the network as an image - pick it from the list, which rescans in the background. Video only, no audio. Needs the free NDI runtime from ndi.video. NDI(R) is a registered trademark of Vizrt NDI AB." },
      { "NDI Out", "Utility", "source name", "Publishes the connected image as a named NDI video source on the local network (OBS, vMix, Resolume, NDI Studio Monitor). Video only, no audio. Needs the free NDI runtime from ndi.video; without it the node says so and everything else works. NDI(R) is a registered trademark of Vizrt NDI AB." },
      { "Noise", "Source", "noise bm ridged voronoi worley edges white perlin simplex width height octaves lacunarity warp contrast brightness rgb color low high", "Procedural noise: value, fBm, ridged, Voronoi, Worley edges, white, plus gradient Perlin and Simplex (single and fBm) that are identical on every GPU. Domain warping, octaves and colour mapping included." },
      { "Normals", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat shade flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Recomputes vertex normals - 'flat shade' gives hard per-face edges instead of smooth shading, 'flip' inverts which way every face points." },
      { "Note Capturer", "Notes", "loop use global record play stop clear notes", "A MIDI recorder and looper. Record captures whatever plays into it (tempo-relative, so it stays in sync if the BPM changes); Play loops that phrase back on top of the live input, which always passes through regardless of transport state. Loop toggles whether playback repeats or stops after one pass. Quantize snaps every recorded onset to the nearest grid line the moment recording stops. A topology rebuild elsewhere in the patch (any cable connect/disconnect) no longer clears a take - only Clear does. Like every other recorder in this app, the recording itself doesn't survive save/load - only loop/quantize do." },
      { "Note Echo", "Notes", "rate beats seconds repeats decay transpose per repeat mute dry notes", "Repeats every incoming note event, delay ms apart, with velocity decaying and pitch shifting per repeat - a delay line for notes rather than audio. The original note always passes through first; the repeats are on top of it, not instead of it." },
      { "Note Expression", "Modulators", "source pressure slide low high", "Each note's own MPE pressure or slide. Turn on mpe on MIDI Notes, then cable this into an Analog or Wavetable knob (cutoff, volume, wavetable position, ...): every voice follows the pressure or slide (CC74) of the finger playing it, between low and high, smoothed over 5 ms so it never zippers. Into anything that is not a synth knob it follows the channel moved last." },
      { "Note Filter", "Notes", "major natural minor harmonic melodic dorian phrygian lydian mixolydian locrian pentatonic blues whole tone chromatic root lo range low hi high chance use global notes", "A gate on a note's pitch: scale snaps it to the nearest degree of the chosen scale/root, range drops anything outside lo..hi, and chance randomly drops the rest. A note that gets dropped has its note-off dropped with it, so nothing hangs." },
      { "Note Merge", "Notes", "", "The system's only note fan-in point: up to four note inputs merged into one output stream, in timestamp order. Each input's notes stay independent voices matched by voice id, not pitch - so two inputs playing the same note at the same time sound as two overlapping voices, not a collision." },
      { "Note Router", "Notes", "round robin random probability chain notes", "The system's only note fan-out point: one input, four distinct outputs. Round Robin cycles through them, Random picks one per note, Chain advances only when the pitch changes (a held note stays put), and Probability rolls each output independently - a note can end up on several outputs at once, or (rarely) none, in which case it falls back to output 1. A note's whole lifetime (on through off) always stays on the output(s) it started on." },
      { "Note Sequencer", "Notes", "steps rate beats seconds gate percent use global note0 vel0 en0 note1 vel1 en1 note2 vel2 en2 note3 vel3 en3 note4 vel4 en4 note5 vel5 en5 note6 vel6 en6 note7 vel7 en7 note8 vel8 en8 note9 vel9 en9 note10 vel10 en10 note11 vel11 en11 note12 vel12 en12 note13 vel13 en13 note14 vel14 en14 note15 vel15 en15 step timing 32t", "A self-playing step sequencer, up to 16 steps. Drag a bar's tall upper area to set that step's pitch, drag the thin strip below it to set velocity, click the strip to toggle the step on/off. Steps sets how many loop, rate is either synced to tempo (a note division) or free-running in seconds, gate is how much of each step the note actually sounds for." },
      { "Note Stack", "Notes", "stack semi0 enabled0 semi1 enabled1 semi2 enabled2 semi3 enabled3 semi4 enabled4 semi5 enabled5 semi6 enabled6 semi7 enabled7 use global notes", "Layers transposed copies of every incoming note on top of the original - eight independent semitone voices, each switched on or off on its own. The dry note always sounds; the enabled voices are added to it, not instead of it. The set of voices is captured when a note starts, so switching one off mid-note never leaves it hanging." },
      { "Note Strum", "Notes", "strum ms notes", "Spreads the notes of a chord across time instead of firing them together - strumMs per voice, in ascending pitch order, with each note's original gate length preserved. One knob: at 0 it is a passthrough, and the further up it goes the more the chord reads as strummed rather than struck." },
      { "Note Switcher", "Notes", "rate beats seconds manual slot bar", "Cycles between up to four connected note inputs every N beats or seconds, or pins to one slot with 'manual' - the note-cable counterpart of Switcher (2D) and Switcher 3D. When the active slot changes, new note-ons come only from the new slot, while notes already held on the old one still get their note-offs passed through, so nothing hangs." },
      { "Note Transpose", "Notes", "transpose semitones use global notes", "Shifts every incoming note's pitch by a fixed number of semitones." },
      { "Note to CV", "Modulators", "range low high glide ms notes", "Converts a note stream's pitch into a modulator, so which note is playing can drive any parameter - a filter cutoff, a warp amount, pan. It is a pitch tracker, not an envelope: it holds the last note's pitch on release rather than falling back toward 0 (that's Envelope's job). rangeLow/High set which note range maps onto the full 0..1 span, glide smooths the jump between notes." },
      { "Null", "Compositing", "", "A pass-through node: its output is exactly its input, unchanged. Useful as a stable junction point to branch a cable to several destinations, or as a placeholder while rewiring." },
      { "Null 3D", "3D", "geo", "A pass-through node for geometry: its output is exactly its input mesh, unchanged. Useful as a stable junction point to branch geometry to several destinations." },
      { "Null Modulator", "Modulators", "constant", "Pass-through modulation node that accepts an incoming modulator and forwards it to its output. Useful for monitoring, signal routing, or placeholders." },
      { "OSC Receive", "Utility", "port address low high", "Listens on a UDP port for Open Sound Control messages matching an address pattern, and reports the last received value as a modulator (remapped through low/high). Behaves like LFO/Random - patch its output onto any slider's modulation pin. To drive the patch itself from a script or controller instead - set, query or listen to any param, add, remove or connect nodes - send OSC to 127.0.0.1:9100 (/infinite/node/<index>/<param>); no node needed." },
      { "OSC Send", "Utility", "host port address epsilon interval ms", "Sends its patched modulator input as an Open Sound Control message (address + float) to a host:port over UDP, on change (past an epsilon) or at least every interval - the one node in the patch with no output of its own." },
      { "Ocean", "3D", "resolution amplitude wavelength steepness direction choppiness octaves color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius texture", "A simulated ocean surface mesh - Gerstner-style waves with amplitude, wavelength, steepness, choppiness, direction and octaves for layered swell." },
      { "Octahedron", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "An 8-faced platonic solid." },
      { "Optical Flow", "Compositing", "resolution full half quarter levels window iterations view vectors colour image", "How far each part of the picture moved since the last frame, as a vector per pixel (red and green carry x and y, in pixels of the input; blue is speed). Pyramidal Lucas-Kanade on the GPU. View Colour shows direction as hue and speed as brightness. Use it to push particles or displace a picture along the motion of a video." },
      { "Oscillator", "Synths", "freq frequency glide bend pitch fm depth osc pm wave waveform sine triangle saw square fine octave semi phase unison detune filter lp hp bp notch comb cutoff reso resonance pan attack amp decay sustain release oct notes", "A synth oscillator with four classic waveforms (sine, triangle, saw, square), interactive amp envelope, unison, filter, hard sync, and fine/coarse tuning. With no note cable connected, it free-runs at a set frequency; connect a note cable and it becomes polyphonic and envelope-gated." },
      { "Output", "Utility", "record fps include audio image format video export path offline duration seconds preroll frames png jpg mp4 mov 15s 30s 45s 60s render", "Terminal node. Shows the final image, exports a PNG, and records an H.264 .mov at a chosen frame rate. Recording captures the cooked output, so what you see is what is written." },
      { "Palette", "Modulators", "path swatches swatch count order sort luminance weight hue blend strip steps smooth min chroma include neutrals shift saturation brightness spread live rate sample choose reference re extract ref", "Samples colours from a reference image, loaded here or patched in - a patched cable overrides the loaded file, but the file is kept so unplugging falls back to it. Drag its 'out' onto the square dot beside any colour swatch to bind it - each new cable takes the next swatch, and clicking a bound swatch steps it. Its image output is a gradient of the palette." },
      { "Partials", "Synths", "path pitch formant partials morph noise release loop sample load notes", "Playable resynthesis: a loaded sample is analysed once into tracked partials plus the noise they leave behind, then every note plays it back additively at the note's pitch. Transposing keeps the sample's formants where they were, so a voice an octave up still sounds like the same voice; formant moves them on purpose. partials thins the stack from the top, morph crossfades partial by partial into a second sample, speed walks through the sample faster or slower without changing pitch, noise sets the residual, and loop repeats the sample while the note is held. 8 voices, note-driven; analysis runs on a background thread." },
      { "Particle System", "3D", "max particles rate sec emit shape point sphere box disc radius lifetime life random initial spread dir gravity drag turbulence turb start end color from along normal copy source colour mass time curve more", "A particle emitter that simulates on the graphics card, up to about a million particles (the CPU fallback holds 200,000). Set the shape, rate, lifetime, launch speed, spread and direction, gravity, drag and turbulence, mass, time scale, and each particle's size and colour from birth to death, with a curve for each. Patch any geometry or points into the emit pin and turn on emit from input to be born on its surface or points instead of the shape; speed along normal launches along the surface, and copy source colour keeps the source's colour. The output is points: patch it into Render 3D, Point Trails for comet tails, or the cloud pin of Instance on Points to stamp a shape on every particle." },
      { "Path", "Modulators", "shape circle line figure helix spiral lissajous beat phase turns ping pong follow slice axis contour index curve geo", "Outputs a moving 3D point (X/Y/Z, each patchable separately) travelling around a built-in shape (circle, helix, spiral, lissajous, etc.) at a beat-synced speed, or along the points of a patched-in geometry/curve source instead." },
      { "Pattern", "Modulators", "step0 step1 step2 step3 step4 step5 step6 step7 step8 step9 step10 step11 step12 step13 step14 step15 length beats step glide between steps smooth low high bipolar fit bar division", "A 16-step sequencer: drag the bar grid (paint across bars by dragging horizontally), choose how many steps to use or fit them to the transport's time signature, and it loops through them one step every N beats. Optional glide between steps and a bipolar display mode." },
      { "PaulStretch", "Synths", "path stretch paul win window 46ms 93ms 186ms 372ms 743ms 49s 97s phase rand pitch shift finetune fine tune freq unison detune start end loop rate fix load record audition", "Extreme time-stretching - the PaulStretch algorithm, built for stretch factors where a few seconds becomes minutes of evolving ambient texture rather than a recognisable sample. Large-window FFT with phase randomisation is what keeps it smooth instead of stuttery: at phase randomisation 1 the result is pure texture, lower values keep more of the original's transient character. Also offers spectral pitch shift, frequency shift and unison detune. Load a file or record into its 'record in' pin." },
      { "Phaser", "AudioEffects", "cutoff depth order spread rate div analog audio", "A cascade of allpass stages (order, 2-8) sweeping around cutoff at rate/depth - each pair of stages adds one more notch to the comb. Spread offsets the right channel's sweep phase for width." },
      { "Piano", "Synths", "model grand rhodes wurlitzer tremolo hardness tone decay detune stiffness body release notes", "Physically modelled piano. model picks a grand, a Rhodes or a Wurlitzer. On the electrics the hammer hits a steel tine or reed and the pickup makes the sound: play harder and it barks, pickup moves the bar closer, fork mistunes the tone bar (beating for sustain), bell is the short metallic overtones of the attack, speaker blends from the direct out into the amp, and tremolo is the Wurlitzer's vibrato or a Suitcase's stereo pan. On the grand, every note is a felt hammer striking one to three unison strings that stretch their upper partials sharp, as a real piano's do, on a soundboard. The harder you play the shorter the hammer touches the string and the brighter it gets. hardness is the felt (soft and round to hard and bright), tone how fast the upper partials die against the fundamental, decay how long a held note sings, detune how far apart the unison strings are (the slow beating and the two-stage decay of a real piano), stiffness how far the partials stretch (0 is perfectly harmonic), body blends from the bare strings into the soundboard, and release is how fast the dampers stop a note after note-off; the top octave and a half has no dampers and rings on. 16 voices, note-driven." },
      { "Piano Roll", "Notes", "transpose vel velocity use global thru notes", "Plays the notes of the Piano Roll page linked to it - a MIDI lane in the Timeline, laid out in clips you draw, cut and loop like any other clip. It follows the transport, plays each clip as drawn (loops unrolled, chance rolled fresh on every play), and sends pitch bend, pressure and timbre curves along with the notes. transpose and vel act on everything the page plays; the notes input passes through and merges in (switch thru off to drop it). The Global Scale button snaps every played note to the project key and scale. A copy of the node starts unlinked, so one page never drives two nodes." },
      { "Pie", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A circular wedge / pie-slice - Inner Ratio controls how much of the circle is cut away." },
      { "Pitch Bend", "Notes", "bend semitones notes", "A hand-driven bend wheel, patched inline in the note chain like Note Transpose. Unlike a transpose (which can only re-pitch a note as it attacks), moving this knob slides every note currently held through it in real time - drag it while a chord rings and the chord bends, no need to route it onto a synth's own bend knob. Default range is +/-2 semitones, the standard wheel range." },
      { "Pitch Shifter", "AudioEffects", "pitch grain analog spectral audio", "A two-tap delay-line pitch shifter: pitch in semitones, grain size in ms (shorter grains track fast material better but sound more granular). No formant correction - octave shifts will chipmunk/deepen the timbre along with the pitch." },
      { "Plane", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A flat subdivided plane - one of the Geometry 3D primitives." },
      { "Plugin", "AudioEffects", "plugin format name accepts notes sidechain state bypass map slots open configure", "Hosts a third-party Audio Unit effect. Drag one in from the Plugins panel (Rescan there indexes what is installed; the list is cached, so launching never rescans), or drop a .component bundle from Finder. \"open\" shows the plugin's own editor in a separate window. The sliders on the body are plugin parameters you chose to expose: turn \"configure\" on and touch a control in the plugin's own window and it appears here as a mapped row - or pick one from the dropdown, since not every plugin's editor tells the host what was touched. Each mapped row is a real param with its own modulation pin, so a Ramp or Envelope can drive it. Right-click a row to unmap it. With nothing loaded, or bypassed, audio passes through unchanged. A plugin with a sidechain input (most compressors and gates) gets a \"sidechain\" pin: patch the key signal there, and switch the plugin itself to its external sidechain." },
      { "Point Trails", "3D", "length sample every width fade taper colour color from points gradient over age head tail match by particle index point limit clear", "Draws where each point has been: points in, a mesh of tails out, so Particle System -> Point Trails -> Render 3D gives comet tails you can fly the camera through. Length is how many past positions each tail keeps; Sample every takes only every Nth frame, for longer tails at the same cost. Width is the head's thickness, Taper thins the tail and Fade darkens it. Colour comes from the points or a head-to-tail gradient. Match by Particle ID starts a new tail when a particle is reborn; Index follows each point whatever happens. Tails freeze while the input stops moving; Clear starts them over. It draws only the tails, not the points themselves: patch the source into Render 3D as well as into Point Trails to see both. It needs points that move (a Particle System, or a cloud you animate); a still cloud leaves no tails." },
      { "Points to Vertices", "3D", "alive only inherit material color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius points", "Point cloud in, mesh out: one vertex per point, with no edges or faces. This is the bridge that lets a cloud (Particle System, a Distribute node, Image to Points) re-enter the mesh operators that only know how to walk a Mesh. 'alive only' skips dead particles." },
      { "Polygon", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A regular polygon - Sides sets how many." },
      { "Pose Track", "Modulators", "mirror smoothing hold ms present body head wrist arm spread lean", "Tracks one person's body from an image or camera wire: head, both wrists, how high each arm is raised, how far apart the wrists are, lean and distance. Keep the upper body in view. A small preview shows what is tracked. Needs the Tracking pack (Settings > Extensions)." },
      { "Predictive Coloring", "Prediction", "learning self normalize wander profile local learn", "Learns what 'graded' footage looks like for you and grades incoming frames toward it. Press Learn on already-graded footage to build a target profile (or leave self normalize on to auto-level/contrast without one); mix blends the grade in. Wander makes the grade gently drift among looks the profile has actually seen instead of solving to the exact same answer every frame - 0 is the old fixed behavior, higher wanders more, scaled down automatically for a thin or low-confidence profile." },
      { "Predictive Modulator", "Prediction", "constant rank fit data low high learn", "Wire a modulator in and press Learn: it passes the signal through while it listens, fits a small dynamical model (Dynamic Mode Decomposition) of its shape, then on Stop free-runs that model on its own - decoupled from the live cable - instead of replaying the exact recording. Rank sets how many delayed copies of the signal the fit is built from (2, 3, 4 or 8); the readout shows the fit's spectral radius, how close the learned pattern sits to the edge of instability." },
      { "Predictive Notes", "Prediction", "source stray memory length spread velocity low range high use global model learn notes", "Wire a note chain in and press Learn: it listens (passing the notes through), learns the pitches, rhythm, lengths and velocities as a variable-order Markov model, then plays on its own in that style. Stray at the bottom replays the phrase, the middle plays in character, the top ignores the model and picks freely in range. The learned notes are saved with the patch." },
      { "Predictive Quantize", "Prediction", "notes", "A groove quantizer, not a grid one: wire a note chain in and it always listens to the actual spacing between your onsets while also correcting them in the same pass - no Learn/Stop, it just keeps adapting the more you play. The learned spacing profile is global: shared by every Predictive Quantize in every patch, and it keeps only your most recent onsets, so it tracks how you're playing now rather than an ever-growing history. Mix at 0 is untouched, mix at 1 snaps fully onto the nearest learned spacing. Unlike Quantizer's fixed grid, this follows however you actually played it, including swing or a template that isn't on a clean subdivision." },
      { "Predictive Rhythm", "Prediction", "stray memory root c0 d0 e0 f0 g0 a0 b0 c1 d1 e1 f1 g1 a1 b1 c2 d2 e2 f2 g2 a2 b2 c3 d3 e3 f3 g3 a3 b3 c4 d4 e4 f4 g4 a4 b4 c5 d5 e5 f5 g5 a5 b5 c6 d6 e6 f6 g6 a6 b6 c7 d7 e7 f7 g7 a7 b7 c8 d8 e8 f8 g8 a8 b8 c9 d9 e9 f9 g9 model learn notes", "Wire any note source in and press Learn, same as Predictive Notes. It learns the rhythm, note lengths and velocity as its own habit, but learns pitch as an interval from a 'root' note instead of an absolute pitch - so what comes back out reads as a repeating pattern anchored on one note with occasional deviation (think C2 C2 C2 D3 C2 C2 C2), not a free melody. Root auto-detects to the most common note you played when Learn finishes; change it afterward with the dropdown to transpose the whole learned pattern without relearning." },
      { "Predictive Velocity", "Prediction", "notes", "A learned dynamics curve, not a hand-picked one: wire a note chain in and it always listens to the velocities you play while also remapping them in the same pass - no Learn/Stop, it just keeps adapting the more you play. The learned curve is global: shared by every Predictive Velocity in every patch, and it keeps only your most recent notes, so it tracks how you're playing now rather than an ever-growing history. Mix at 0 is untouched, mix at 1 snaps fully onto the learned range, so your loudest playing maps to your own real loudest instead of a theoretical 127. Unlike Velocity Curve's one fixed shape, this follows your own dynamics." },
      { "Prism", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A prism - an extruded polygon with Sides sides." },
      { "Projection", "Utility", "corner pin perspective mesh grid width height match res pattern live crosshairs diagonals color bars combined target r0 c0 c1 c2 c3 c4 c5 c6 c7 r1 r2 r3 r4 r5 r6 r7 corners all flip", "Warp, corner-pin and perspective-correct an image for projectors, flat walls, or curved screens, with built-in alignment test patterns and custom resolution target." },
      { "Proximity Lines", "3D", "radius max per point lines links thickness alive only inherit material color metallic roughness opacity emission points", "Joins points that are closer than Radius with thin lines (plexus and constellation looks). Point cloud in, mesh of lines out. Max per point and Max lines keep a dense cloud from turning solid; each pair is drawn once, nearest first. Thickness is the line radius. Lines take their colour from the points when the points have colour." },
      { "Pyramid", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A pyramid - Sides sets the base's side count (4 = classic square pyramid)." },
      { "Quantizer", "Notes", "grid div bars bar 2t 4t 8t 16t 32t notes", "Snaps incoming note-on timing forward to the nearest grid line, at a chosen note division." },
      { "Ramp", "Source", "linear radial angular diamond spiral repeat clamp mirror width height angle center offset gamma dither stops stop count at stop0 color0 stop1 color1 stop2 color2 stop3 color3 stop4 color4", "Generates a gradient from scratch (no input) between up to 8 user-set colour stops, at a chosen angle, scale and offset. Gamma and dither smooth out visible banding." },
      { "Random", "Modulators", "rate smooth low high beats hz maths per voice", "A new random value every step, with adjustable smoothing between steps. The rate is synced to a note division, free beats or Hz. Seeded and deterministic, so rewinding replays the same sequence." },
      { "Random Note Generator", "Notes", "lo range low hi high major natural minor harmonic melodic dorian phrygian lydian mixolydian locrian pentatonic blues whole tone chromatic root rate beats seconds wander max step use global groove swing timing 32t", "A generative source that free-runs on its own clock (synced to tempo or free-running seconds) rather than only reacting to a knob edit: each new note is the previous one plus a small random step (wander sets the max semitones), clamped to lo..hi and snapped to the chosen scale - a bounded random walk, not independent-per-step randomness, so the line wanders rather than jumps around." },
      { "Range to Range", "Modulators", "no cable constant low high clamp range", "Remaps one modulator's input range onto a different output range - patch in a 0..1 LFO and remap it to -2..2, for example." },
      { "Reaction Diffusion", "Compositing", "preset coral mitosis maze spots worms holes width height feed kill diffuse steps frame per source influence low color high reseed", "Gray-Scott chemical simulation, six presets. Needs no input; patch one in and its luminance varies the feed rate so the pattern grows differently through light and dark." },
      { "Rectangle", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A filled/stroked rectangle, with an optional corner radius." },
      { "Remove Background", "Compositing", "detect subject mac os person cutout mask only background feather threshold edge contrast auto refresh video frames bg color opacity remove", "On-device segmentation via the OS - no model download, no network, no key. Subject mode needs macOS 14, Person mode macOS 12. Segmentation is expensive, so the mask is computed on this interval rather than every frame; for video, raise the interval or use auto-refresh." },
      { "Render 3D", "3D", "engine raster path trace samples pt bounces ambient occlusion ao radius depth field dof aperture focus distance blades rotation ratio bit float offline supersample width height pass render color linear raw normals mist object index emission shadow environment start falloff intensity threshold cavity world screen both shading view rendered solid lighting single matcap specular studio ridge valley curvature motion blur shutter frame center end max projection perspective orthographic equirect cubemap 3x2 fisheye dome cylindrical fov ortho angle tilt lens cam lat min lon orbit azimuth elevation target near far light rim env sky horizon ground use as background bg opacity test cull backfaces sprite shape circle square antialias 2x 4x 8x tonemap aces reinhard ag neutral exposure hdr bloom cast shadows resolution quality bias softness strength scene more material geo camera", "Rasterizes the geometry/camera/light/material graph into an image. Antialiasing is reduced automatically at large output sizes to stay within GPU limits. Scenes over ~2 million triangles get noticeably heavier to render. An HDRI node patched into the env input replaces the procedural sky gradient for background, reflections and ambient light. With hdr on (the default for a new node) light is kept above white until one tonemap at the end, so bloom glows only from what is truly bright; the background colour stays exact. Projection also offers Equirect 360 (2:1 for VR players; add 360 metadata with a tool such as Spatial Media Metadata Injector), Cubemap 3x2 and Fisheye dome (dome angle and tilt); these draw the scene six times, so they cost about six times a normal render, and they use the built-in camera." },
      { "Resonator Bank", "AudioEffects", "root freq structure poles decay scatter spread analog damp harmonic odd audio", "Tuned bank of up to 16 parallel bandpass resonators excited by incoming audio. Four harmonic/tuning structures (Harmonic, Odd, Chord, Metallic) with decay (T60), scatter detune and stereo spread." },
      { "Resynthesize", "Effects", "drift quilt cellular spectral shatter chaos mutation feedback source pull steps per beat auto iterate loop path pad corner effect0 amount0 effect1 amount1 effect2 amount2 effect3 amount3 rec play clear randomise fx", "Each generation reads the previous one, so the image drifts away from the source. The XY pad blends four named mutation effects assigned to its corners - drag the orb to mix them. Randomise re-rolls which four effects sit in the corners, and the orb's path can be recorded, looped and replayed in time." },
      { "Resynthesize 3D", "3D", "displace jitter smooth twist bulge extrude faces subdivide squash chaos auto step steps per beat triangle budget randomise geo", "The mesh equivalent of Resynthesize: each generation applies a weighted mix of geometry operators to the previous one, drifting the shape over time. 'step' advances one generation manually, 'auto step' runs it continuously, 'randomise' re-rolls the seed." },
      { "Reverb", "AudioEffects", "decay damping predelay width analog audio", "An 8-line feedback delay network: size (room size), decay (RT60 in seconds), damping (darkens and speeds up the tail), predelay (gap before the reverb starts), width (stereo spread, full at 1 down to mono at 0) and mix. Algorithmic only - no convolution engine." },
      { "Revolve", "3D", "axis angle segments caps profile", "Spins a profile curve around the X, Y or Z axis to make a surface of revolution: vases, bowls, rings, wine glasses, columns. Draw half the outline (a Curve works well) and set the axis it turns about. A closed profile turned all the way round is a solid; a part-turn is closed with flat caps when Caps is on; an open profile gives an open shell. Segments sets how smooth the turn is." },
      { "Rigid Bodies", "3D", "collider box sphere convex hull mass iterations friction bounce linear damping angular gravity ground height walls wall velocity vel spin kick time more geo", "Drops every separate piece of the input mesh as a rigid body - box, sphere or convex-hull collider - that falls, collides and stacks on a ground plane and optional walls. Mass, friction, bounce, damping, gravity, starting velocity and spin, and a timed kick. The same patch plays back identically every time. 'Reset' drops them again." },
      { "Ring", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner thick radius sides inner ratio rotation fill color opacity stroke feather bg", "A donut / annulus - a circle with a hole; corner/thick controls the ring's thickness." },
      { "Ring Mod", "AudioEffects", "freq waveform analog sine triangle audio", "Multiplies the input by an oscillator (freq, waveform) - true ring modulation, not amplitude modulation, so the original frequencies are replaced by sum/difference sidebands rather than just scaled." },
      { "Rounded Cube", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides corner radius bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A cube with rounded edges/corners - 'corner radius' sets how rounded." },
      { "Rounded Rect", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner thick radius sides inner ratio rotation fill color opacity stroke feather bg", "A rectangle with rounded corners - like Rectangle but with the corner radius exposed as its own control." },
      { "Sampler", "Synths", "path pitch finetune start end decay fade loop rate fix reverse pingpong load record audition rev notes", "A sample player: load a file (or drag one in from the Samples search panel), or record from the audio input pin. Click the waveform to audition from that point, or use the audition button - both preview this node on its own dedicated voice, independent of the transport and any note cable, and never cut off or get cut off by an incoming note. Drag the waveform's two edge handles to set the loop range (start/end). pitch/finetune are coarse/fine tuning, speed is a -2..2 varispeed control (negative plays backward), volume is the output level. loop/rev/p-p control what happens at the range edges: loop wraps or bounces (ping-pong) instead of stopping, reverse flips the base direction. fade in / fade out are lengths in ms applied at the start and end of every pass through the range (each loop lap, ping-pong leg or one-shot), so a loop dips at its seam instead of clicking; 3 ms each by default, 0 for a hard edge. Patches saved with the old loop xfade load with the defaults. With no note cable connected, it free-runs on the transport - starts the moment you hit space, stops when you stop it; connect a note cable and it becomes polyphonic instead, each note played back at the pitch offset from middle C. Spacebar always silences every voice this node is making." },
      { "Saturator", "AudioEffects", "model1 amount1 model2 amount2 model3 amount3 routing feedback tube serial parallel audio", "Three saturation stages, each with its own curve (tube, tape, diode, fold, rectify, crush) and amount (up to 36 dB of drive; crush goes from 16 bits down to 2). Routing wires them serial, parallel (averaged), mid-side (stage 1 on mid, 2 on side, 3 on left/right), 3-band (low/mid/high split at 250 Hz and 2.5 kHz) or feedback (serial, with the output fed back through a 1 ms delay; the feedback knob is the loop gain after the drive, so it colours the sound and never howls). Runs at 8x with anti-aliased curves." },
      { "Screw", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise turn invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Sweeps the input profile around an Axis in a helical path - Steps sets resolution, Turns the number of revolutions, Rise/turn the pitch, Radius offsets the sweep outward." },
      { "Sculpt", "3D", "data open 3d view geo brush", "Holds a sculpt painted in the 3D View: press Open in 3D View, or select the item and press Ctrl+Tab (or the brush chip). Amount blends it in, so an LFO or audio can drive it; level subdivides the input first. Chain Sculpt nodes to layer sculpts. Patch any 2D node into brush and each dab takes its shape: bright moves, dark holds. If the input's points change, the sculpt stops applying until they come back or it is cleared." },
      { "Select", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise all index normal random facing sign invert add append selected move along color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Marks a subset of faces - by index range, position along an axis, normal direction, random chance, or within a radius - for downstream ops (Delete Selected / Transform Selected / Extrude Selected) to act on. Invert flips the selection, 'add to selection' unions with whatever was already selected." },
      { "Set Vertex Color", "3D", "source flat normal index random palette texture color ramp offset geo", "Writes per-element colour - vertex colours on a mesh, per-particle colour on a point cloud, whichever the input actually carries. 'source' picks where the colour comes from: a Flat colour, a two-colour Ramp, Random per element, a patched texture sampled at each element's UV, or a patched Palette node's swatches (offset steps which swatch starts the run). Nothing downstream has to know which - Render 3D reads whatever ended up there." },
      { "Shadertoy", "Source", "formula width height knob animate buffers no buffer st image buf common st0 st1 st2 st3 st4 st5 st6 st7 names edit shader channel0 channel1 channel2 channel3", "Runs a shader pasted from shadertoy.com as it is: mainImage, buffers A-D and the Common tab. ch0-ch3 are the iChannel0-3 image pins; an unwired channel reads its buffer. A 'uniform float name; // lo..hi' line becomes a modulatable knob." },
      { "Shape", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "The base 2D vector-primitive node - pick any of its 20 shapes from the dropdown, with fill, stroke, feather and background controls. Each shape also has its own directly-spawnable named node (Circle, Hexagon, Star, ...) that just starts on that shape." },
      { "Shape Resonator", "AudioEffects", "tune decay damping modes audio shape", "Rings the vibration modes of the shape on the 'shape' pin, like striking that object. Tune sets the lowest mode's pitch; the other modes follow from the shape's geometry, so a flat plate sounds bell-like and a long bar nearly harmonic. Pos is where it is struck and heard from: a mode stays silent when struck on its node line. With no shape connected it rings a flat rectangular plate." },
      { "Sketch", "Source", "code svg name width height animate field next param map edit sketch", "Draws an image from a JavaScript sketch you write in the node - loops, arrays and recursion with a p5.js-style API (rect, circle, line, beginShape, push/pop, translate, rotate, text). param(\"name\", default, lo, hi) in the script becomes a knob you can modulate. A mistake shows its line number and the last working picture stays up. Drop an .svg on the canvas (or onto a Sketch) to animate it by id with svgSet, svgText, svgBox and svgDraw. No file or network access." },
      { "Sketch 3D", "3D", "code animate field next param map edit sketch 3d", "Builds 3D geometry from a JavaScript sketch you write: draw(t) calls box, sphere, cylinder, cone, torus, tube and beginShape/vertex/endShape, moved with translate, rotate and scale (push/pop to nest). param(\"name\", default, lo, hi) makes a modulatable knob. Patch it into Render 3D or any geometry operator. A mistake shows its line number and the last working mesh stays. No file or network access." },
      { "Slicer", "Synths", "path slice by onsets grid count division 8t 16t sensitivity pitch finetune attack decay crossthrough slices load record audition re notes", "Chops a sample into slices and maps them chromatically to the keyboard from MIDI note 36 upward - note 36 plays slice 1, 37 plays slice 2, and so on. A note past the last slice is silent; it does not wrap round to slice 1. Load a file (or drag one in from the Samples panel), or record from the audio input pin. slice by picks where the boundaries come from: onsets runs transient detection over the sample on a background thread, grid divides it arithmetically at the *global transport tempo* (there is no per-node bpm - change the tempo and the grid follows). sensitivity is the detection threshold and is the only control that re-runs the analysis; onsets just caps the result to the strongest N, and division/slice by recompute boundaries instantly. Click a slice band in the waveform to audition it, and in onsets mode drag any marker to move a boundary by hand - hand-edited markers are saved with the patch. Two separate controls decide how long a slice lasts: crossthrough sets whether playback may run PAST the slice's own next onset (off by default - each slice stops where the next begins), while decay shapes only the amplitude envelope, reading 'hold' at the top of its throw where the slice stays at full level. So: crossthrough off + hold is the classic tight chop; crossthrough off + a decay ends at whichever comes first; crossthrough on + hold plays through the rest of the sample; crossthrough on + a decay is a one-shot with a tail over the rest of the break. attack extends each slice's own fade-in from instant up to half a second." },
      { "Slideshow", "Source", "folder hold duration transition time fade slide left right wipe zoom fit native best proportional width height choose", "Plays the supported images in one folder in alphabetical order. Hold and transition time follow the global transport; Native Size keeps source pixels 1:1, Best Fit stretches to fill, and Proportional Fit preserves aspect." },
      { "Smooth", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only move count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Iteratively averages each vertex toward its neighbours (a Laplacian smooth) - Iterations and Strength control how much it relaxes. On a low-poly mesh like a Cube there's no extra geometry between the corners to round out, so raise Pre-subdivide first to see rounded edges." },
      { "Smoothing", "Modulators", "no cable constant time spring frequency damping maths", "Smooths another modulator to damp jittery or steppy sources like Random or Pattern. Amount is a moving average whose response is the same at any frame rate (older patches keep the per-frame version); Time uses a time constant in seconds; Spring follows the input like a mass on a spring, with frequency and damping, and can overshoot." },
      { "Solidify", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels move thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Gives a flat or open surface real Thickness, turning it into a solid shell. 'keep original' also retains the source surface." },
      { "Spatial Mixer", "Utility", "azimuth az0 elevation el0 distance dist0 width width0 gain0 mute0 solo0 lock0 az1 el1 dist1 width1 gain1 mute1 solo1 lock1 az2 el2 dist2 width2 gain2 mute2 solo2 lock2 az3 el3 dist3 width3 gain3 mute3 solo3 lock3 az4 el4 dist4 width4 gain4 mute4 solo4 lock4 az5 el5 dist5 width5 gain5 mute5 solo5 lock5 az6 el6 dist6 width6 gain6 mute6 solo6 lock6 az7 el7 dist7 width7 gain7 mute7 solo7 lock7 az8 el8 dist8 width8 gain8 mute8 solo8 lock8 az9 el9 dist9 width9 gain9 mute9 solo9 lock9 az10 el10 dist10 width10 gain10 mute10 solo10 lock10 az11 el11 dist11 width11 gain11 mute11 solo11 lock11 room bass mono hz hrtf limiter track head air pods bit24 render format index live record directory recenter limit kemar wav flac bit binaural choose model", "Mixes audio in 3D for headphones and plays it straight to the output (no output pin; it also records its own WAV/FLAC, 16 or 24 bit, always facing front): each input is a dot around a head, and its angle, distance and height (scroll on a dot) change how it is heard. Drop a cable on the empty + pin to add a source; alt-drag a dot for its level; H pins a source in front of your head. Ears use a measured dummy-head set (MIT KEMAR) or a spherical-head model; a limiter holds -1 dB and the meter shows loudness. Head tracking (AirPods Pro/Max etc.) works on macOS 14+ only and turns the room with your head; elsewhere the head stays fixed." },
      { "Spec Blur", "AudioEffects", "blur time tilt diffuse diffusion freeze analog audio", "Streaming phase vocoder (N=2048, hop 512) that smears spectral magnitude in time. Transients dissolve into a harmonic cloud with tilt, phase diffusion and freeze. Latency is 42.7 ms (2048 samples); default mix is pinned at 1.0." },
      { "Spectral Synth", "Synths", "spec scan loop ping pong one shot run hz bpm manual scrub rate bars bar 2t 4t 8t 16t 32t direction per voice part partials choice freq logarithmic musical linear harmonic series mel chromatic tet min max root octave semi fine glide color luma mono hue stereo pan rgb split shimmer spectral bands thresh threshold contrast brightness invert width unison detune filter lp hp bp notch comb cutoff reso resonance drive attack amp decay sustain release oct fwd rev image note", "Image-to-sound additive resynthesis, in the MetaSynth tradition: any image, glyph, drawing or live video patched in is read as a spectrogram and rebuilt out of 64-256 sine partials. X is time (the scan axis), Y is frequency (linear or logarithmic, between min/max Hz), brightness is amplitude, and in Hue-Pan colour mode the hue becomes stereo position. The scan can sync to the transport at a note division, free-run at its own speed, or be scrubbed by hand with position - and with a note cable connected it transposes polyphonically." },
      { "Spectrum Slide", "AudioEffects", "slide audio", "Morphs the sound into the one on the 'to' pin by sliding its spectral peaks toward the other's positions instead of cross-fading, so a 440 Hz tone becomes 880 Hz by passing through 660 Hz. Slide sets how far along the way; with nothing on 'to' it passes the sound through. Latency is 42.7 ms (2048 samples)." },
      { "Sphere", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A UV sphere - latitude/longitude subdivision." },
      { "Splitter", "Utility", "bands split1 split2 split3 copy audio", "The explicit fan-out point for audio: an ordinary audio output feeds exactly one destination, so sending one signal to several places needs this node. Its own output is the one exempt from that rule. In copy mode it is a plain copy. Set bands to 2, 3 or 4 and the pins become frequency bands, low to high, split by Linkwitz-Riley crossovers at split1-3; the bands add back up to the input with a flat response, so you can process each band on its own and mix them again." },
      { "Star", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A star with adjustable point count (Sides) and Inner Ratio for how deep the points cut in." },
      { "Star 3D", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides depth bevel segments inner ratio super n2 n3 p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A 3D extruded star - 'depth' sets extrusion depth, 'inner ratio' how deep the points cut in. Named with a '3D' suffix because the 2D Shape node already has its own 'Star'." },
      { "Stereo", "AudioEffects", "width pan bass mono audio", "Mid/side width control: width scales the side signal (0 = mono, 1 = unchanged, 2 = exaggerated), pan balances the result, bass mono folds everything below a frequency back to mono so low end survives a mono system. The bar shows live L/R correlation." },
      { "String", "Synths", "exciter pluck bow strike tone decay stiffness body box guitar harp violin cello release hardness pressure noise notes", "Physically modelled string: every note is a waveguide string tuned exactly to its pitch, on a shared wooden body. exciter plucks it, bows it (the bow keeps it sounding while the note is held) or strikes it with a felt hammer that gets brighter the harder you hit. position is where along the string it is excited, measured from the bridge (a quarter of the way in silences every 4th harmonic, as on a real string). tone sets how bright it stays as it rings, decay how long the note rings while held, stiffness stretches the upper partials sharp like a piano or a metal string, body blends from the bare string into the body's resonances (body type picks whose: a small box, or a guitar, harp, violin or cello body measured from recordings), and release is how fast the damper stops it after note-off. hardness is the pick (soft and dull to hard and bright); pressure is how hard the bow presses (light slips and sounds airy, heavy sticks and grits) and noise adds rosin noise to the bow. 8 voices, note-driven." },
      { "Stutter", "AudioEffects", "rate div time ms steps gate mask bars audio", "Records the first `grain` fraction of each tempo-synced (or free-ms) cycle, then loops that captured slice for the rest of the cycle before recording fresh audio next cycle - a beat-repeat glitch effect." },
      { "Subdivide", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius move levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Subdivision surface. Each level roughly quadruples the triangle count, so higher levels get expensive fast; Smooth controls how much it rounds corners." },
      { "Superellipse", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A 'squircle' - a shape between a rectangle and an ellipse, tunable via Inner Ratio." },
      { "Supershape", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A superformula-based shape - 'depth', 'tooth depth' and 'hub hole' warp it into gear-like or organic silhouettes." },
      { "Sweep", "3D", "start end twist caps profile radius sides path", "Carries a profile curve along a path curve to make a surface: pipes, rails, rims, cables, ribbons. Patch the shape into the first pin and the route into the second; with no profile it sweeps a round one, so a path alone gives a tube. The profile does not spin where the path bends. Start and End scale taper it, Twist turns it along the way, and Caps closes the ends of a closed profile on an open path. A closed profile on a closed path is a watertight ring." },
      { "Switcher", "Compositing", "unit beats seconds every interval crossfade manual slot", "Cycles between its connected inputs every N beats or seconds, with an optional crossfade. Can be pinned to one input with 'manual'." },
      { "Switcher 3D", "3D", "unit beats seconds every interval crossfade manual slot geo", "Cycles between up to four connected geometry inputs every N beats or seconds, forwarding whichever one is active. Can be pinned to one input with 'manual'. Unlike the 2D Switcher, there is no crossfade - it always hard-cuts, since interpolating between two arbitrary meshes' topology isn't generally well-defined." },
      { "Syphon In", "Utility", "app name server uuid", "Receives real-time video from another macOS application over Syphon - Resolume, OBS, TouchDesigner, MadMapper, Unreal, Unity - as a zero-copy shared GPU texture (IOSurface). Pick a server from the list; it rescans periodically, so a server that starts after this node does will appear." },
      { "Syphon Out", "Utility", "server name", "Broadcasts video, 3D renders, or visual shaders to other macOS applications in real-time via zero-copy GPU texture sharing." },
      { "Teardrop", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A teardrop / droplet outline." },
      { "Tetrahedron", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A 4-faced platonic solid." },
      { "Text", "Source", "text font name color tracking align left center right justified word wrap width height fit box line spacing outline only helvetica neue", "Renders text using any font installed on the system, with size, colour, tracking, alignment and position." },
      { "Text 3D", "3D", "text font depth bevel tracking rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius helvetica texture", "Extrudes text into a 3D mesh, with depth, bevel and letter tracking, using any font installed on the system." },
      { "Texture", "Source", "texture voronoi brick magic wave musgrave checker gradient clouds marble wood width height contrast brightness low color high distance euclidean manhattan chebyshev minkowski feature f1 f2 smooth edge sphere radius randomness exponent smoothness cell row offset mortar bias depth distortion profile bands direction detail phase dimension lacunarity octaves hard turbulence noise", "Blender-standard procedural textures: Voronoi, Brick, Magic, Wave and Musgrave, each with its own parameter block." },
      { "Time Machine", "Compositing", "length resolution full half quarter invert image delay map", "Shows each pixel from a different moment: it keeps the last frames and a grey map (the second input) says how far back every pixel looks, black is now and white is the oldest frame. A left-to-right ramp, the default with no map, gives a slit-scan. Length sets how many frames are kept (up to 60), Resolution how large they are stored (memory grows with it), Invert flips the map." },
      { "Torus", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A ring/donut solid - 'tube' sets the tube radius relative to the overall ring." },
      { "Torus Knot", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides bevel segments super n2 n3 inner p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A knotted torus - a tube swept along a (p,q) knot path rather than a plain circle." },
      { "Trails", "Compositing", "decay zoom rotate drift hue shift blend max add screen clear", "A pre-wired feedback loop: decaying accumulation with drift, zoom, rotation and hue rotation. Reach for this before wiring a Feedback loop by hand." },
      { "Transform", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin beat radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Moves, rotates and scales the input mesh by a fixed offset - the geometry equivalent of the 2D Transform effect." },
      { "Transform Selected", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step rotate pivot spin beat radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Moves, rotates and scales only the faces marked by an upstream Select op, optionally sliding them along their own normals instead of a fixed direction." },
      { "Transient Shaper", "AudioEffects", "attack sustain audio", "Boosts or cuts a signal's transient hits (attack) separately from its sustained body (sustain), via a fast/slow envelope-difference detector - no threshold or ratio to set, unlike a compressor." },
      { "Tremolo", "AudioEffects", "depth shape stereo phase rate div sine triangle audio", "A unipolar gain envelope traced by a sub-audio LFO (rate/sync, shape, stereo phase, depth) - amplitude modulation, not ring modulation (see Ring Mod above): the original frequencies pass through unchanged, only the level rises and falls." },
      { "Triangle", "Source", "shape circle ellipse rectangle rounded rect triangle polygon star ring cross line hexagon heart arrow crescent gear superellipse pie teardrop chevron blob width height aspect corner radius sides inner ratio rotation fill color opacity stroke feather bg", "A filled/stroked equilateral-style triangle." },
      { "Triangulate", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only move count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Re-triangulates the mesh; Jitter randomizes how each face is split, for a more organic, less uniform look." },
      { "Tube", "3D", "winding fix shape plane cube sphere icosphere torus cylinder cone knot capsule tube pyramid prism helix supershape tetrahedron octahedron dodecahedron rounded mobius strip klein bottle gear 3d star disc arrow detail sides inner radius bevel segments super n2 n3 p2 p3 rot spin color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface sheen iridescence thickness anisotropy rotation dispersion alpha cutoff texture", "A hollow cylinder - 'tube' sets the wall's inner radius." },
      { "Twist", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only angle count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments depth margin turns rise invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Twists the mesh, or a cloud's points, around a chosen Axis by Angle - the further a point is along that axis, the more it rotates. On GPU points it runs on the GPU." },
      { "UV Project", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth smart cube cylinder sphere margin turns rise invert append selected move along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Writes real UVs so a texture sticks to the mesh as it moves or deforms. Smart splits it into islands of faces facing the same way and packs them into the square; Cube, Cylinder and Sphere project from the bounds. Use a Mapping node set to UV, or none, to read them." },
      { "Union", "3D", "merge union intersect difference material from inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface radius geo", "Boolean union: fuses two or more closed, manifold solids into one, keeping their combined outer surface." },
      { "VMPC", "Source", "pad0 path div pad opacity start end fade fadein fadeout pad1 one shot gate loop rate bars bar 2t 4t 8t 16t 32t pad2 pad3 pad4 pad5 pad6 pad7 pad8 pad9 pad10 pad11 pad12 pad13 pad14 pad15 transition cut crossfade dip black time ms hold frame last soundtrack selected load folder clear notes video audio", "How to use: drop video clips onto the pads (or click an empty pad, or Load... / Folder... for the first 16 clips of a folder), wire the video out into an Output, then click a pad or send notes into the notes input - notes 36 to 51 play pads 1 to 16. A 16-pad video player laid out like the MPC: pad 1 is bottom-left, every tile shows a frame of its clip, its number and mode, and every pad has its own CV pin. A hit follows the pad's mode: one shot plays the clip's window once and a new hit restarts it; gate plays while held and fades out over fade out on release; loop toggles a looping playback. The picture is the most recently hit pad that is still playing; transition (cut, crossfade, dip to black over time) sets how it takes over from what was showing, and when it ends the previous playing pad comes back the same way. With nothing playing the picture goes to black, or holds its last frame when hold frame is on. Click selects a pad (right-click selects without playing); the rows below edit it: sync and rate (Synced latches a hit to the next grid line, a synced loop restarts on every division), start and end (the window, as a percentage of the clip), speed (negative plays backwards), opacity, mode, and fade in / fade out (ms). The filmstrip shows the selected clip with its window; hover it to read the time. The audio out carries the visible clips' own soundtracks when soundtrack is on, each at the weight its picture is shown with. Every param of every pad can be modulated; a cable stays on its own pad when you select another, and an orange dot marks a pad with a modulated param. Clip paths and pad settings are saved with the patch; the clips are re-opened on load. The idea comes from Ricardo Palmieri's Infinite-Turbo fork; this is a fresh implementation." },
      { "Velocity Curve", "Notes", "curve notes", "Reshapes incoming note velocity through a response curve (soft/linear/hard, or a custom curve) - the note-chain equivalent of a keybed velocity curve setting." },
      { "Velocity to CV", "Modulators", "range low high notes", "Converts how hard each note is played into a modulator (its 0..1 velocity), so touch can drive any parameter - brightness, pan, a filter opening on accents. It holds the last note's velocity through release. range low/high pick which velocities map onto the full 0..1 span (swap them to invert). The pitch counterpart is Note to CV." },
      { "Vibrato", "Modulators", "rate hz", "An LFO wired straight to pitch. It is a modulator, not a note-chain node - it has no note input on purpose, because a free-running wobble has no single note to attach to. Patch its output onto a synth's pitch/bend mod dot (e.g. Wavetable's 'bend' knob)." },
      { "Video", "Source", "path loop audio start trim end choose video", "Plays a video file. Position follows the transport, so it pauses with everything else. Loop and speed (including reverse) are available. Also outputs the clip's own audio track, if it has one, on the same transport-driven clock as the picture (audioEnabled/volume)." },
      { "Video In", "Source", "active device resolution mirror", "Captures a live camera as an image source - the built-in camera, external USB webcams, and Continuity Camera (an iPhone used as a webcam). 'mirror' flips it horizontally, which is usually what you want for a front-facing camera; 'resolution' picks the capture format. macOS will prompt for camera permission the first time this node cooks, so it stays idle until it is actually in a patch." },
      { "Viewport", "Compositing", "", "Shows its input at actual pixel size in its own resizable window, separate from the small node preview - useful for judging detail without zooming the whole canvas." },
      { "Voice Spread", "Modulators", "linear golden ratio primes alternate count low high", "A different value for each note of a chord. Cable it into an Analog or Wavetable knob (cutoff, pan, detune, ...) and every note gets its own setting between low and high, by its place among the keys held when it started: linear spaces them evenly, golden ratio scatters them so each new note lands in the biggest gap, primes spaces them unevenly, alternate goes out from the middle, one side then the other. After count notes the pattern repeats. Into anything that is not a synth knob it gives the first note's value." },
      { "Volume", "Compositing", "shape fog smoke cloud density height center noise wind color light azimuth elevation intensity ambient scatter anisotropy steps render max distance cam fov target more image", "Fog, smoke or a cloud drawn over a picture, from drifting noise that the wind moves. Fed by a Render 3D node it sits in that scene: it uses the render's camera and solid objects hide the haze behind them. Steps sets quality while you work; render steps is used when rendering offline." },
      { "Voronoi Cells", "3D", "plane xy xz yz alive only max points inset", "Point cloud in (a mesh is flagged red and ignored), one polygon cell per point out, for cracked-glass, cell and fracture looks: every cell is the region closer to its point than to any other. Points on the outer hull have unbounded cells and are skipped. 'inset' pulls each cell toward its point to leave gaps between them." },
      { "Wave Terrain", "Synths", "wt orbit circle ellipse lissajous lemniscate spiral scanline chan channel luminance red green blue alpha edge magnitude center radius ratio phase offset rotation scan morph pan freq frequency octave semi fine glide unison detune stereo width attack amp decay sustain release filter lp hp bp notch comb cutoff reso resonance drive oct texture note", "Wave terrain synthesis: an image patched in is read as a height field z = T(u,v), and the oscillator's waveform is whatever a closed orbit traced across that terrain reads back. Orbit type/centre/radius/ratio decide the path, so moving the orbit is a timbre control rather than a pitch one - and because the terrain is an ordinary image input, a Noise, Draw, Video or Reaction Diffusion node upstream reshapes the sound live. Each cycle is band-limited through a 10-level mip pyramid, so it stays alias-free however sharp the source image is." },
      { "Wavetable", "Synths", "freq frequency glide bend pitch fm depth wt pm table basic shapes harmonics odd only formant pulse vocal bell saturate comb drift sub glass sweep drawbar reso saw marimba tine ep prime walsh square static vowel path tri dirty analog multi transistor clip chebyshev golden ratio fibonacci cathedral pipe staircase dual octave clang metal modern squelch bitcrush morph phase fold mirror peak ring mod digital crunch talk choir monster growl nasal throat whisper soprano vowels box wah vibraphone plucked string church chime acoustic reed brass lead slap bass kalimba cosmic drone glitch shard granular sieve void abyss high overdrive shimmer cloud nebula pan unison detune stereo width semi fine random randomize warp am rm pd hard asym flip quantize rectify even pinch skew filter lp hp bp notch cutoff resonance attack amp decay sustain release oct notes", "Two independent wavetable engines with unison, filter, and pitch/filter/amp envelopes, mixed by an A/B control. With no note cable connected, it free-runs at a set frequency; connect a note cable and it becomes polyphonic and envelope-gated." },
      { "Wavetable Shaper", "AudioEffects", "table drive bias smooth stereo basic shapes harmonics audio", "Uses a wavetable frame as a waveshaping transfer curve: the input sample's amplitude selects a phase into the table, the table's value there is the output. Drive past 0dB pushes the phase past the table's ends, where it wraps instead of clipping - true wavefolding, not distortion. Position morphs the curve across the table's 8 frames, smooth crosses to a lower-harmonic (darker) version of the same curve." },
      { "Wind", "Synths", "instrument clarinet sax flute brass breath tone noise vibrato attack release notes", "Physically modelled wind instrument: every note is a bore blown by a clarinet reed, a sax reed on a conical bore, a flute's air jet or brass lips. breath is how hard you blow (soft and dark up to loud and bright; blow too softly and a reed will not speak), tone is how bright the bell lets it be, noise is the air in the breath, vibrato a 5.5 Hz swell in the breath, and attack and release how fast the breath comes and goes. 8 voices, note-driven." },
      { "Wireframe", "3D", "operation op transform array subdivide solidify extrude wireframe triangulate normals explode twist smooth mirror screw select delete decimate bevel inset uv project inherit selection only count offset rot step pivot spin radial radius levels move thickness keep original flat flip axis by iterations weld seam steps ratio lock border width segments angle depth margin turns rise invert append selected along normal color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface geo", "Replaces solid faces with a wireframe tube running along each edge, at a chosen Thickness." },
      { "Wrap", "3D", "cylindrical spherical nearest surface axis radius fit around offset blend flat shade flip normals inherit color metallic roughness opacity shading emission ior transmission specular clearcoat subsurface source target", "Bends or conforms the source input onto the target input. Cylindrical rolls it around one axis at the target's radius with no distortion at all - letterforms, spacing and extrusion depth survive intact, which is what curves 3D text around a sphere or cylinder. Spherical adds the same bend the other way so long text also curves over the poles. Nearest Surface snaps every vertex to the closest point on the target instead: right for conforming a dense mesh to irregular geometry, but it squashes flat text. With a target connected the bend radius follows the target's size, so scaling the target moves the source with it - radius scale tunes it as a multiplier. With no target, radius sets the bend outright." },
      { "addnoise", "Effects", "headroom", "Adds random per-pixel grain, re-randomised every frame. Amount sets how strong it is." },
      { "alpha from luma", "Compositing", "invert headroom", "Derives a new alpha channel from the image's own brightness, so a black background becomes transparent with nothing to key against. 'invert' flips which end is solid, for a white-on-black source." },
      { "alpha invert", "Compositing", "headroom", "Swaps transparent for solid and back (alpha = 1 - alpha), leaving the colour alone - the 'invert matte' switch a key would otherwise need a second node to get." },
      { "alpha levels", "Compositing", "low high gamma headroom", "The Levels remap applied to the alpha channel only: Low/High clamp and normalise the matte's range (choking a soft edge tighter or spreading it wider) and Gamma bends the falloff between them. The go-to cleanup pass after Chroma Key or Alpha from Luma." },
      { "bloom", "Effects", "threshold intensity radius linear headroom", "Isolates pixels above a brightness Threshold, blurs them outward by Radius, and adds the glow back at Intensity - classic HDR-style bloom." },
      { "boxblur", "Effects", "radius linear quality headroom smooth classic", "Blurs by averaging a flat square of neighbouring pixels - cheaper and blockier than Gaussian Blur. Radius sets the box size." },
      { "chroma key", "Compositing", "key color tolerance softness spill removal matte headroom keyed", "Removes a chosen Key Colour (green/blue-screen style), matched in a brightness-independent colour space. Tolerance/Softness shape the edge, Spill Removal desaturates colour-cast fringes, 'show: Matte' previews the alpha instead of the keyed result." },
      { "color adjustments", "Compositing", "brightness contrast black point white gamma cyan red magenta green yellow blue hue shift saturation lightness vibrance shadows midtones highlights curve pivot row bwenabled weight sat model slope offset power cdl headroom more", "All-in-one grading chain: Brightness/Contrast, Levels, Colour Balance, HSL, Vibrance, Tone Shaper (lift/gamma/gain-style S-curve), Channel Mixer, then an optional Black & White stage - so a common grade doesn't need eight separate nodes wired in series." },
      { "coloroverlay", "Compositing", "color opacity headroom", "Flat-tints the image toward a chosen Colour at a given Opacity." },
      { "convolve", "Effects", "k11 k12 k13 k21 k22 k23 k31 k32 k33 divisor bias spread headroom", "A user-editable 3x3 convolution kernel (k11-k33) - blur, sharpen, edge-detect and emboss are all just different numbers in this grid. Divisor and Bias adjust the result, Spread scales the sample distance, Mix blends with the original." },
      { "crop", "Effects", "left right top bottom fill headroom transparent zoom", "Crops in from each edge (Left/Right/Top/Bottom). 'outside' chooses what happens to the cropped-away area: stays transparent, the kept region zooms to fill the frame, or gets replaced with a Fill colour." },
      { "diffuseglow", "Effects", "radius linear headroom", "Screens a blurred copy of the whole image back over itself, glowing everything rather than just bright spots (compare Bloom, which is threshold-based)." },
      { "displace", "Effects", "map linear headroom", "Offsets each pixel using a second patched-in image's red/green channels as a displacement map, or a built-in animated wave if nothing is patched. Map Scale tiles the map." },
      { "dither", "Compositing", "levels headroom bayer", "Reduces the image to a few Levels per channel like Posterize, but spreads the rounding error as a fixed pattern so gradients keep their tone instead of banding. Mode picks an ordered Bayer matrix (2, 4 or 8) or a noise pattern; Mix blends back toward the original." },
      { "dropshadow", "Compositing", "offset color opacity headroom", "Offsets a blurred copy of the image's alpha behind it as a shadow, in a chosen Colour, Offset X/Y and Opacity." },
      { "edge outline", "Effects", "thickness threshold color headroom", "Detects edges via a luminance gradient and draws them as flat-Colour outlines at a chosen Thickness and Threshold, over the original image." },
      { "edge sobel", "Effects", "invert headroom", "Classic Sobel edge detection: outputs the gradient magnitude as greyscale edges. Invert flips black and white." },
      { "emboss", "Effects", "angle distance keep color premul headroom grey over colour", "Turns edges into a relief/bump look by differencing the image against itself offset along Angle/Distance. 'style: Over colour' keeps the original colours and adds the emboss on top; 'Grey' replaces the image with a flat emboss." },
      { "exposure", "Compositing", "exposure linear headroom", "Multiplies brightness by powers of two, like a camera's exposure stop (compare Levels' linear/gamma remap)." },
      { "gaussianblur", "Effects", "radius quality linear headroom smooth classic", "Blurs the image with a Gaussian-weighted kernel - a smooth, natural blur. Radius sets how far it samples; Quality Smooth samples every pixel for a cleaner result." },
      { "glitch", "Effects", "kind detail linear headroom slice shift rgb", "Six glitch algorithms behind one 'kind' dropdown: Slice Shift (blocky RGB-split rows), RGB Shift, Scanlines, Blocks (jittered tiles), Wave, and Datamosh (sliced/shuffled rows with colour smear). Amount/Detail control strength/scale, Speed animates it, Seed reseeds the randomness." },
      { "gradientmap", "Compositing", "shadow color highlight headroom", "Remaps luminance onto a two-colour gradient (Shadow to Highlight), Photoshop Gradient Map-style. Mix blends with the original colour." },
      { "halftone", "Effects", "angle color headroom mono colour", "Renders the image as a dot pattern like offset printing. Scale sets dot density, Angle rotates the dot grid, 'style: Colour' uses three angled CMY-style dot layers instead of one greyscale layer." },
      { "invert", "Compositing", "headroom", "Inverts every colour channel (alpha untouched) - a photographic negative. No parameters." },
      { "kaleidoscope", "Effects", "segments rotation zoom center headroom", "Slices the image into angular Segments around a centre and mirrors each one, kaleidoscope-style. Rotation spins the pattern, Zoom scales it." },
      { "lensdistortion", "Effects", "barrel chromatic chroma zoom headroom", "Simulates a camera lens: Barrel bows the image in or out, Chromatic separates the colour channels' distortion for fringing, Zoom scales the result." },
      { "liquify", "Effects", "linear headroom", "Flows pixels around using animated Perlin-style noise, like a liquid warp. Scale sets the flow's feature size, Speed animates it." },
      { "lookup", "Compositing", "channel offset ends headroom luminance exact red wrap", "Recolors using a second patched-in image as a 1D palette strip - this pixel's Luminance (or a chosen channel) indexes across it. Offset shifts the index, Mix blends with the original." },
      { "luma key", "Compositing", "low high softness invert matte headroom keyed", "Keys out a brightness range (Low-High) instead of a colour, with Softness at the edges and Invert to flip which range is kept. 'show: Matte' previews the alpha." },
      { "lut", "Compositing", "lut interp headroom tetrahedral trilinear original", "Grades the image through a second patched-in HALD/strip LUT image - an N x N-sliced colour cube encoded as a flat strip. LUT Size must match the LUT image's slice count, Mix blends with the original." },
      { "mirror tile", "Effects", "tiles headroom", "Tiles the image and alternately mirrors each tile so the edges line up seamlessly, unlike a plain repeat. Tiles sets how many repeats." },
      { "motionblur", "Effects", "angle distance linear headroom", "Smears the image along a straight line, like camera or subject motion. Angle sets the direction, Distance how far it smears." },
      { "normal map", "Effects", "strength invert premul headroom open gl normals direct height", "Derives a tangent-space normal map from the image's luminance treated as a height field, for use as a bump/normal input elsewhere. 'output' can show the raw Normals, the source Height, or the gradient's Slope instead." },
      { "opacity", "Compositing", "opacity headroom", "Scales the whole image's existing alpha by Opacity - a uniform fade that keeps the colour untouched. Unlike Color Overlay, nothing is tinted; unlike a Blend's opacity, the transparency is baked into the image and travels with it down the chain." },
      { "outerglow", "Compositing", "color linear headroom", "Adds a soft glow of a chosen Colour around the image's alpha edge, blurred outward. Amount controls strength." },
      { "pinchpunch", "Effects", "radius center linear headroom", "Pulls pixels toward, or pushes them away from, a centre point. Amount above 1 punches outward, below 1 pinches inward." },
      { "pixelate", "Effects", "block headroom", "Chunks the image into flat colour blocks. Block Size sets how large each block is." },
      { "posterize", "Compositing", "levels headroom", "Reduces the image to a fixed number of tonal Levels per channel, producing flat colour bands." },
      { "premultiply", "Compositing", "headroom premultiply unpremultiply", "Converts between premultiplied alpha (colour already scaled by its own alpha) and straight alpha. Only reach for this when something looks wrong at the edges: dark fringing on a composite usually means straight alpha needs premultiplying, bright halos the reverse." },
      { "radialblur", "Effects", "center linear headroom", "Blurs outward from a centre point, like a zoom or spin blur. Amount sets the strength, Center X/Y the origin." },
      { "ripple", "Effects", "amplitude wavelength phase center linear headroom", "Displaces pixels outward from a centre in concentric waves. Amplitude is wave height, Wavelength the spacing, Phase animates it." },
      { "set alpha", "Compositing", "headroom", "Replaces the alpha channel outright with the luminance of a second patched-in image - hand-drawn mattes, a Shape, a Ramp, or another branch's 'show alpha' output. With nothing patched into the second input the image is forced fully opaque instead." },
      { "show alpha", "Compositing", "headroom", "Shows the alpha channel as a greyscale image, fully opaque - white is solid, black is transparent. A viewer, not an edit: it replaces the colour so you can see the matte a key produced, and is usually the first thing to reach for when a composite is going wrong." },
      { "symmetry", "Effects", "axis center flip headroom mirror", "Mirrors the image about the X axis, Y axis, or both, from a chosen centre point. Flip additionally reverses the whole image before mirroring." },
      { "threshold", "Compositing", "threshold headroom", "Converts to pure black or white based on luminance, split at Threshold." },
      { "transform", "Compositing", "translate rotation crop flip headroom", "Translates, scales, rotates, and flips (horizontal/vertical) the whole image. Scale X/Y let you stretch non-uniformly on top of the overall Scale. Crop X/Y symmetrically crop the source in from each axis before the rest of the transform is applied." },
      { "twirl", "Effects", "angle radius center linear headroom", "Rotates pixels increasingly the closer they are to a centre point, like a whirlpool. Angle is the twist amount, Radius how far it reaches." },
      { "unsharpmask", "Effects", "radius headroom", "Unsharp mask: blurs a copy of the image and adds back the difference, exaggerating edges. Amount is the strength, Radius how wide an edge it reacts to." },
      { "vignette", "Effects", "radius softness center headroom", "Darkens the image toward the edges, framing the centre. Radius and Softness shape the falloff, Center X/Y offsets it." },
   };
}
